// ── Performance: BoundedMessageStore (gated behind PERF_FLAGS.BOUNDED_MESSAGES) ──
var _PERF_BOUNDED_MESSAGES = true; // Feature flag — matches PERF_FLAGS.BOUNDED_MESSAGES
var _boundedStoreMaxInMemory = 200;
var _boundedStoreSessionId = '';
var _boundedStorePersistInFlight = false;
var _boundedStoreEnabled = false; // Set to true once initialization completes

/**
 * Initialize the bounded message store for a given session.
 * Called when a project/session becomes active.
 */
function _boundedStoreInit(sessionId) {
  if (!_PERF_BOUNDED_MESSAGES) return;
  _boundedStoreSessionId = sessionId || '';
  _boundedStoreEnabled = true;
}

/**
 * Add a message to the bounded store. If over the 200-message cap,
 * persists the oldest messages to SQLite via IPC.
 */
function _boundedStoreAdd(msgObj) {
  if (!_boundedStoreEnabled) return;
  // chatMessageStore is still the source of truth; this handles overflow
  if (chatMessageStore.length > _boundedStoreMaxInMemory) {
    _boundedStorePersistOverflow();
  }
}

/**
 * Persist overflow messages to SQLite via IPC.
 * Removes the oldest messages from chatMessageStore beyond the 200 cap.
 */
function _boundedStorePersistOverflow() {
  if (_boundedStorePersistInFlight) return;
  var overflowCount = chatMessageStore.length - _boundedStoreMaxInMemory;
  if (overflowCount <= 0) return;

  var toPersist = chatMessageStore.splice(0, overflowCount);
  _boundedStorePersistInFlight = true;

  // Convert to StoredMessage format for persistence
  var messages = toPersist.map(function(m, idx) {
    return {
      id: (m.id || ('msg-' + Date.now() + '-' + idx + '-' + Math.random().toString(36).slice(2))),
      role: m.role || 'assistant',
      content: m.content || m.text || '',
      agent: (m.meta && m.meta.label) || undefined,
      isCmd: (m.meta && m.meta.type === 'command') || false,
      timestamp: m.timestamp || (Date.now() - (overflowCount - idx) * 1000),
      sessionId: _boundedStoreSessionId,
    };
  });

  eapi().invoke('persist-overflow-messages', { messages: messages }).then(function() {
    _boundedStorePersistInFlight = false;
  }).catch(function() {
    // Retry once after 100ms
    setTimeout(function() {
      eapi().invoke('persist-overflow-messages', { messages: messages }).then(function() {
        _boundedStorePersistInFlight = false;
      }).catch(function() {
        // Both attempts failed — put messages back at the front
        chatMessageStore.unshift.apply(chatMessageStore, toPersist);
        _boundedStorePersistInFlight = false;
      });
    }, 100);
  });
}

/**
 * Load older messages from SQLite for scroll-back.
 * Returns a promise resolving to { messages, hasMore, oldestTimestamp }.
 */
function _boundedStoreLoadOlder(beforeTimestamp, limit) {
  if (!_boundedStoreEnabled) {
    return Promise.resolve({ messages: [], hasMore: false, oldestTimestamp: 0 });
  }
  return eapi().invoke('load-older-messages', {
    sessionId: _boundedStoreSessionId,
    beforeTimestamp: beforeTimestamp,
    limit: limit || 50,
  });
}

/**
 * Get the total message count (in-memory + persisted).
 */
function _boundedStoreGetTotalCount() {
  if (!_boundedStoreEnabled) return Promise.resolve(chatMessageStore.length);
  return eapi().invoke('get-overflow-count', { sessionId: _boundedStoreSessionId }).then(function(result) {
    return chatMessageStore.length + (result.count || 0);
  });
}

/**
 * Switch the bounded store to a new session.
 */
function _boundedStoreSwitchSession(sessionId) {
  if (!_PERF_BOUNDED_MESSAGES) return;
  _boundedStoreSessionId = sessionId || '';
}

/**
 * Clear the bounded store for the current session.
 */
function _boundedStoreClear() {
  if (!_boundedStoreEnabled) return;
  eapi().invoke('clear-overflow-session', { sessionId: _boundedStoreSessionId }).catch(function() {});
}

