        var spec = embeddingProviderSpecs[selectedProvider] || embeddingProviderSpecs.ollama;

        var updates = {
          enabled: true,
          incrementalIndexing: incrToggle ? incrToggle.checked : true,
          vectorSearch: vecToggle ? vecToggle.checked : true,
          callGraph: cgToggle ? cgToggle.checked : true,
          connectors: { git: gitToggle ? gitToggle.checked : true, documentation: true },
          embeddingProvider: selectedProvider,
          embeddingModel: 'auto', // Auto-detect best embedding model from provider
          embeddingEndpoint: spec.endpoint,
          embeddingDimensions: spec.dimensions,
        };

        var statusEl = document.getElementById('idx-config-status');
        if (statusEl) statusEl.textContent = 'Saving...';

