            var ck = checks[i];
            var sevColor = ck.severity === 'error' ? 'var(--red)' : ck.severity === 'warning' ? 'var(--yellow)' : 'var(--text-dim)';
            h += '<div style="display:flex;align-items:center;justify-content:space-between;padding:6px 10px;background:var(--bg-input);border:1px solid var(--border-color);border-radius:6px;margin-bottom:4px;">' +
              '<div style="display:flex;align-items:center;gap:6px;">' +
              '<span style="width:8px;height:8px;border-radius:50%;background:' + sevColor + ';"></span>' +
              '<span style="font-size:12px;font-weight:600;color:var(--text-primary);">' + escHtml(ck.name) + '</span>' +
              '<span style="font-size:10px;color:var(--text-dim);">' + escHtml(ck.description || '') + '</span>' +
              '</div>' +
              '<label style="display:flex;align-items:center;gap:4px;cursor:pointer;">' +
              '<input type="checkbox" class="ci-check-toggle" data-check-id="' + ck.id + '" ' + (ck.enabled ? 'checked' : '') + ' style="cursor:pointer;" />' +
              '</label></div>';
