    var execOutput = $$('#exec-output');
    var execMaxTurns = $$('#exec-max-turns');
    var execTimeout = $$('#exec-timeout');
    if (execAutonomy) execAutonomy.addEventListener('change', saveExecConfig);
    if (execOutput) execOutput.addEventListener('change', saveExecConfig);
    if (execMaxTurns) execMaxTurns.addEventListener('change', saveExecConfig);
