// ── Invite Modal ──
function showInviteModal(refCode, senderEmail) {
  var existing = document.getElementById('nn-invite-modal');
  if (existing) existing.remove();
  var overlay = document.createElement('div');
  overlay.id = 'nn-invite-modal';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);display:flex;align-items:center;justify-content:center;z-index:10001;backdrop-filter:blur(4px);';
  var card = document.createElement('div');
  card.style.cssText = 'background:var(--bg-primary,#1e1e2e);border-radius:16px;padding:28px;max-width:400px;width:90%;box-shadow:0 20px 60px rgba(0,0,0,0.5);';
  card.innerHTML = '<h3 style="color:var(--text-primary,#cdd6f4);margin:0 0 4px;font-size:18px;">\u2709\ufe0f Invite a Friend</h3>' +
    '<p style="color:var(--text-dim,#a6adc8);font-size:12px;margin:0 0 16px;">Send an invitation to join NeuroNest using your referral code.</p>' +
    '<div style="display:flex;flex-direction:column;gap:10px;">' +
    '<input id="invite-first" type="text" placeholder="First Name *" style="padding:10px 12px;border-radius:8px;border:1px solid var(--border-color,#45475a);background:var(--bg-input,#313244);color:var(--text-primary,#cdd6f4);font-size:13px;" />' +
    '<input id="invite-last" type="text" placeholder="Last Name (optional)" style="padding:10px 12px;border-radius:8px;border:1px solid var(--border-color,#45475a);background:var(--bg-input,#313244);color:var(--text-primary,#cdd6f4);font-size:13px;" />' +
    '<input id="invite-email" type="email" placeholder="Email Address *" style="padding:10px 12px;border-radius:8px;border:1px solid var(--border-color,#45475a);background:var(--bg-input,#313244);color:var(--text-primary,#cdd6f4);font-size:13px;" />' +
    '</div>' +
    '<div id="invite-error" style="display:none;color:#f38ba8;font-size:12px;margin-top:8px;padding:6px 10px;background:rgba(243,139,168,0.1);border-radius:6px;"></div>' +
    '<div id="invite-success" style="display:none;color:#a6e3a1;font-size:12px;margin-top:8px;padding:6px 10px;background:rgba(166,227,161,0.1);border-radius:6px;"></div>' +
    '<div style="display:flex;gap:8px;margin-top:16px;">' +
    '<button id="invite-send-btn" style="flex:1;padding:10px;font-size:13px;font-weight:600;background:var(--accent,#89b4fa);color:#fff;border:none;border-radius:8px;cursor:pointer;">\u2709\ufe0f Send Invite</button>' +
    '<button id="invite-cancel-btn" style="padding:10px 16px;font-size:13px;color:var(--text-dim,#a6adc8);background:transparent;border:1px solid var(--border-color,#45475a);border-radius:8px;cursor:pointer;">Cancel</button>' +
    '</div>';
  overlay.appendChild(card);
  document.body.appendChild(overlay);

  var cancelBtn = document.getElementById('invite-cancel-btn');
  if (cancelBtn) cancelBtn.addEventListener('click', function() { overlay.remove(); });
  overlay.addEventListener('click', function(e) { if (e.target === overlay) overlay.remove(); });

  var sendBtn = document.getElementById('invite-send-btn');
  if (sendBtn) sendBtn.addEventListener('click', function() {
    var first = document.getElementById('invite-first');
    var last = document.getElementById('invite-last');
    var email = document.getElementById('invite-email');
    var errEl = document.getElementById('invite-error');
    var succEl = document.getElementById('invite-success');
    var firstName = first ? first.value.trim() : '';
    var lastName = last ? last.value.trim() : '';
    var recipientEmail = email ? email.value.trim() : '';
    if (!firstName) { if (errEl) { errEl.textContent = 'First name is required.'; errEl.style.display = 'block'; } return; }
    if (!recipientEmail || recipientEmail.indexOf('@') === -1) { if (errEl) { errEl.textContent = 'Valid email address is required.'; errEl.style.display = 'block'; } return; }
    if (errEl) errEl.style.display = 'none';
    if (succEl) succEl.style.display = 'none';
    sendBtn.disabled = true;
    sendBtn.textContent = 'Sending...';
    eapi().invoke('referral:send-invite', {
      senderRefCode: refCode,
      senderEmail: senderEmail,
      recipientFirst: firstName,
      recipientLast: lastName || undefined,
      recipientEmail: recipientEmail,
    }).then(function(result) {
      sendBtn.disabled = false;
      sendBtn.textContent = '\u2709\ufe0f Send Invite';
      if (result && result.error) {
        if (errEl) { errEl.textContent = result.error; errEl.style.display = 'block'; }
      } else if (result && result.ok) {
        if (succEl) { succEl.textContent = '\u2705 Invite sent! (' + (result.sendCount || 1) + ' total to this recipient)'; succEl.style.display = 'block'; }
        if (first) first.value = '';
        if (last) last.value = '';
        if (email) email.value = '';
        // Mark that invites have been sent
        try { var p = JSON.parse(localStorage.getItem('neuronest-user-profile') || '{}'); p.hasInvites = true; localStorage.setItem('neuronest-user-profile', JSON.stringify(p)); } catch(_e) {}
        // Refresh manage referrals page if it's visible
        var mgrList = document.getElementById('referral-invites-list');
        if (mgrList) {
          setTimeout(function() { showManageReferrals(refCode); }, 1500);
        }
      }
    }).catch(function(err) {
      sendBtn.disabled = false;
      sendBtn.textContent = '\u2709\ufe0f Send Invite';
      if (errEl) { errEl.textContent = err && err.message ? err.message : 'Failed to send invite.'; errEl.style.display = 'block'; }
    });
  });
}


// ── Manage Referrals Page ──
function showManageReferrals(refCode) {
  var mc = $('#main-content');
  mc.innerHTML = '<div class="view-panel view-panel-wide nn-referrals-page" style="padding:0;overflow-y:auto;">' +
    '<style>' +
    '@keyframes nnSpin{to{transform:rotate(360deg)}}' +
    '@keyframes nnFadeIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}' +
    '@keyframes nnSlideIn{from{opacity:0;transform:translateX(-10px)}to{opacity:1;transform:translateX(0)}}' +
    '.nn-referrals-page{--nn-surface:var(--bg-input,var(--surface-container,#313244));--nn-surface-hover:var(--bg-hover,#3b3b52);--nn-border:var(--border-color,#45475a);--nn-text:var(--text-primary,#cdd6f4);--nn-text-sec:var(--text-secondary,#bac2de);--nn-text-dim:var(--text-dim,#a6adc8);--nn-accent:var(--accent,#89b4fa);--nn-bg:var(--bg-primary,#1e1e2e);}' +
    '.nn-referrals-page .nn-header{background:linear-gradient(135deg, color-mix(in srgb, var(--nn-accent) 15%, transparent) 0%, color-mix(in srgb, #a855f7 12%, transparent) 50%, color-mix(in srgb, #f97316 5%, transparent) 100%);padding:32px 32px 24px;border-bottom:1px solid var(--nn-border);position:relative;overflow:hidden;}' +
    '.nn-referrals-page .nn-stat-card{background:var(--nn-surface);border:1px solid var(--nn-border);border-radius:12px;padding:16px 12px;text-align:center;transition:all 0.2s;}' +
    '.nn-referrals-page .nn-stat-card:hover{border-color:var(--nn-accent);transform:translateY(-2px);box-shadow:0 8px 24px color-mix(in srgb, var(--nn-accent) 15%, transparent);}' +
    '.nn-referrals-page .nn-invite-row{display:flex;align-items:center;padding:14px 16px;background:var(--nn-surface);border:1px solid var(--nn-border);border-radius:10px;transition:all 0.3s;}' +
    '.nn-referrals-page .nn-invite-row:hover{border-color:color-mix(in srgb, var(--nn-accent) 40%, transparent);background:color-mix(in srgb, var(--nn-accent) 6%, var(--nn-surface));}' +
    '.nn-referrals-page .nn-btn-resend{padding:6px 12px;font-size:10px;font-weight:600;background:color-mix(in srgb, var(--nn-accent) 12%, transparent);color:var(--nn-accent);border:1px solid color-mix(in srgb, var(--nn-accent) 30%, transparent);border-radius:6px;cursor:pointer;transition:all 0.2s;display:inline-flex;align-items:center;gap:4px;}' +
    '.nn-referrals-page .nn-btn-resend:hover{background:color-mix(in srgb, var(--nn-accent) 22%, transparent);}' +
    '.nn-referrals-page .nn-btn-delete{padding:6px 10px;font-size:10px;font-weight:600;background:color-mix(in srgb, var(--red,#f38ba8) 8%, transparent);color:var(--red,#f38ba8);border:1px solid color-mix(in srgb, var(--red,#f38ba8) 25%, transparent);border-radius:6px;cursor:pointer;transition:all 0.2s;display:inline-flex;align-items:center;gap:4px;}' +
    '.nn-referrals-page .nn-btn-delete:hover{background:color-mix(in srgb, var(--red,#f38ba8) 18%, transparent);}' +
    '.nn-referrals-page .nn-code-card{margin-top:20px;background:var(--nn-surface);border:1px solid var(--nn-border);border-radius:12px;padding:16px 24px;display:flex;align-items:center;justify-content:space-between;}' +
    '.nn-referrals-page .nn-back-btn{padding:8px 18px;font-size:12px;font-weight:500;color:var(--nn-text-sec);background:var(--nn-surface);border:1px solid var(--nn-border);border-radius:8px;cursor:pointer;transition:all 0.2s;}' +
    '.nn-referrals-page .nn-back-btn:hover{border-color:var(--nn-accent);color:var(--nn-accent);}' +
    '.nn-referrals-page .nn-copy-btn{padding:8px 16px;font-size:11px;font-weight:600;background:color-mix(in srgb, var(--nn-accent) 12%, transparent);color:var(--nn-accent);border:1px solid color-mix(in srgb, var(--nn-accent) 30%, transparent);border-radius:8px;cursor:pointer;display:inline-flex;align-items:center;gap:6px;transition:all 0.2s;}' +
    '.nn-referrals-page .nn-copy-btn:hover{background:color-mix(in srgb, var(--nn-accent) 22%, transparent);}' +
    '.nn-referrals-page .nn-send-btn{padding:8px 20px;font-size:12px;font-weight:600;background:var(--nn-accent);color:#fff;border:none;border-radius:8px;cursor:pointer;display:inline-flex;align-items:center;gap:6px;box-shadow:0 4px 12px color-mix(in srgb, var(--nn-accent) 30%, transparent);transition:all 0.2s;}' +
    '.nn-referrals-page .nn-send-btn:hover{transform:translateY(-1px);box-shadow:0 6px 16px color-mix(in srgb, var(--nn-accent) 40%, transparent);}' +
    '</style>' +
    // Header
    '<div class="nn-header">' +
    '<div style="position:absolute;top:-40px;right:-40px;width:180px;height:180px;background:radial-gradient(circle,color-mix(in srgb, var(--nn-accent) 15%, transparent),transparent 70%);border-radius:50%;"></div>' +
    '<div style="position:absolute;bottom:-60px;left:-30px;width:140px;height:140px;background:radial-gradient(circle,color-mix(in srgb, #a855f7 10%, transparent),transparent 70%);border-radius:50%;"></div>' +
    '<div style="display:flex;justify-content:space-between;align-items:flex-start;position:relative;z-index:1;">' +
    '<div>' +
    '<h2 style="margin:0 0 4px;font-size:22px;font-weight:700;color:var(--nn-accent);">Referral Dashboard</h2>' +
    '<p style="margin:0;font-size:12px;color:var(--nn-text-dim);">Track your invites, grow your network</p>' +
    '</div>' +
    '<button id="referrals-back-btn" class="nn-back-btn">\u2190 Back</button>' +
    '</div>' +
    // Referral code card
    '<div class="nn-code-card">' +
    '<div style="display:flex;align-items:center;gap:14px;">' +
    '<div style="width:40px;height:40px;border-radius:10px;background:var(--nn-accent);display:flex;align-items:center;justify-content:center;font-size:18px;">\uD83D\uDD17</div>' +
    '<div>' +
    '<div style="font-size:10px;color:var(--nn-text-dim);text-transform:uppercase;letter-spacing:1.2px;margin-bottom:2px;">Your Referral Code</div>' +
    '<span style="font-size:20px;font-weight:800;color:var(--nn-accent);letter-spacing:3px;font-family:SF Mono,Menlo,monospace;">' + escHtml(refCode) + '</span>' +
    '</div></div>' +
    '<div style="display:flex;align-items:center;gap:8px;">' +
    '<button id="mgr-ref-copy-btn" class="nn-copy-btn" title="Copy referral link"><svg width="14" height="14" viewBox="0 0 24 24" fill="none"><rect x="9" y="9" width="11" height="11" rx="2" stroke="currentColor" stroke-width="2"/><path d="M5 15V5a2 2 0 0 1 2-2h10" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg> Copy Link</button>' +
    '<div id="mgr-ref-copy-toast" style="display:none;font-size:10px;color:var(--green,#40a02b);padding:4px 8px;background:color-mix(in srgb, var(--green,#40a02b) 10%, transparent);border-radius:4px;">\u2705 Copied!</div>' +
    '</div></div>' +
    '</div>' +
    // Stats grid
    '<div style="padding:24px 32px 0;">' +
    '<div id="referral-stats-grid" style="display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:28px;"></div>' +
    '</div>' +
    // Invites section
    '<div style="padding:0 32px 32px;">' +
    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;">' +
    '<div style="display:flex;align-items:center;gap:10px;">' +
    '<h3 style="margin:0;font-size:15px;font-weight:600;color:var(--nn-text);">Invited Users</h3>' +
    '<span id="invite-count-badge" style="padding:2px 8px;font-size:10px;font-weight:600;background:color-mix(in srgb, var(--nn-accent) 15%, transparent);color:var(--nn-accent);border-radius:10px;display:none;">0</span>' +
    '</div>' +
    '<button id="referrals-invite-btn" class="nn-send-btn"><svg width="14" height="14" viewBox="0 0 24 24" fill="none"><path d="M12 5v14M5 12h14" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg> Send Invite</button>' +
    '</div>' +
    '<div id="referral-invites-list" style="font-size:13px;color:var(--nn-text-dim);">' +
    '<div style="display:flex;align-items:center;justify-content:center;padding:40px;gap:8px;">' +
    '<div style="width:20px;height:20px;border:2px solid var(--nn-accent);border-top-color:transparent;border-radius:50%;animation:nnSpin 0.8s linear infinite;"></div>' +
    '<span>Loading referral data...</span></div></div>' +
    '</div></div>';

  var backBtn = document.getElementById('referrals-back-btn');
  if (backBtn) backBtn.addEventListener('click', function() { showLoginView(); });

  // Wire copy button
  var mgrCopyBtn = document.getElementById('mgr-ref-copy-btn');
  if (mgrCopyBtn) {
    var mgrCopyUrl = 'https://neuronest.cc/?ref=' + encodeURIComponent(refCode);
    mgrCopyBtn.addEventListener('click', function() {
      navigator.clipboard.writeText(mgrCopyUrl).then(function() {
        var toast = document.getElementById('mgr-ref-copy-toast');
        if (toast) { toast.style.display = 'block'; setTimeout(function() { toast.style.display = 'none'; }, 2500); }
        mgrCopyBtn.innerHTML = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none"><path d="M5 13l4 4L19 7" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg> Copied!';
        setTimeout(function() {
          mgrCopyBtn.innerHTML = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none"><rect x="9" y="9" width="11" height="11" rx="2" stroke="currentColor" stroke-width="2"/><path d="M5 15V5a2 2 0 0 1 2-2h10" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg> Copy Link';
        }, 2000);
      }).catch(function() {});
    });
  }

  var profile = {};
  try { profile = JSON.parse(localStorage.getItem('neuronest-user-profile') || '{}'); } catch(_e) {}
  var inviteBtn = document.getElementById('referrals-invite-btn');
  if (inviteBtn) inviteBtn.addEventListener('click', function() { showInviteModal(refCode, profile.email || ''); });

  // Fetch referral stats and deleted invites list
  Promise.all([
    eapi().invoke('referral:get-stats', { code: refCode }),
    eapi().invoke('referral:get-deleted-invites', { code: refCode })
  ]).then(function(results) {
    var data = results[0];
    var deletedData = results[1];
    var deletedEmails = (deletedData && deletedData.deleted) ? deletedData.deleted : [];
    // Filter out locally deleted invites
    if (data && data.invites && deletedEmails.length > 0) {
      data.invites = data.invites.filter(function(inv) {
        return deletedEmails.indexOf(inv.recipientEmail) === -1;
      });
    }
    if (data && data.error) {
      var el = document.getElementById('referral-invites-list');
      if (el) el.innerHTML = '<div style="display:flex;align-items:center;gap:8px;color:var(--red,#f38ba8);padding:16px;background:color-mix(in srgb, var(--red,#f38ba8) 8%, transparent);border:1px solid color-mix(in srgb, var(--red,#f38ba8) 20%, transparent);border-radius:10px;"><svg width="18" height="18" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="10" stroke="currentColor" stroke-width="2"/><path d="M15 9l-6 6M9 9l6 6" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg> ' + escHtml(data.error) + '</div>';
      return;
    }
    // Render stats grid
    var statsEl = document.getElementById('referral-stats-grid');
    if (statsEl && data) {
      var stats = [
        { label: 'Clicks', value: data.clicks || 0, icon: '\uD83D\uDD17' },
        { label: 'Installs', value: data.installs || 0, icon: '\uD83D\uDCE5' },
        { label: 'Activations', value: data.activations || 0, icon: '\u2705' },
        { label: 'Invites Sent', value: data.invitesSent || 0, icon: '\u2709\uFE0F' },
        { label: 'Conversion', value: (data.conversionRate || 0).toFixed(1) + '%', icon: '\uD83D\uDCC8' },
      ];
      var sh = '';
      for (var si = 0; si < stats.length; si++) {
        var st = stats[si];
        sh += '<div class="nn-stat-card" style="animation:nnFadeIn 0.4s ease ' + (si * 0.08) + 's both;">' +
          '<div style="font-size:24px;margin-bottom:6px;">' + st.icon + '</div>' +
          '<div style="font-size:22px;font-weight:800;color:var(--nn-accent);margin-bottom:2px;">' + st.value + '</div>' +
          '<div style="font-size:9px;color:var(--nn-text-dim);text-transform:uppercase;letter-spacing:0.8px;font-weight:500;">' + st.label + '</div>' +
          '</div>';
      }
      statsEl.innerHTML = sh;
    }
    // Render users and invites list
    var listEl = document.getElementById('referral-invites-list');
    if (listEl && data) {
      // Combine users (from referral link) and invites (sent manually) into one display
      var allUsers = data.users || [];
      var invites = data.invites || [];
      var totalCount = allUsers.length + invites.length;
      var badge = document.getElementById('invite-count-badge');
      if (badge) { badge.textContent = totalCount; badge.style.display = totalCount > 0 ? 'inline-block' : 'none'; }

      if (totalCount === 0) {
        listEl.innerHTML = '<div style="text-align:center;padding:48px 20px;color:var(--nn-text-dim);">' +
          '<div style="font-size:48px;margin-bottom:12px;opacity:0.6;">\uD83D\uDCE8</div>' +
          '<div style="font-size:14px;font-weight:500;margin-bottom:4px;color:var(--nn-text-sec);">No referral users yet</div>' +
          '<div style="font-size:12px;">Share your referral link or click "Send Invite" to start growing your network!</div>' +
          '</div>';
        return;
      }

      // Build a set of activated user emails to cross-reference with invites
      var activatedEmails = [];
      for (var aui = 0; aui < allUsers.length; aui++) {
        if (allUsers[aui].activated && allUsers[aui].email) {
          activatedEmails.push(allUsers[aui].email.toLowerCase());
        }
      }

      // Filter invites to only those not already in users list
      var filteredInvites = [];
      for (var fi = 0; fi < invites.length; fi++) {
        var fInv = invites[fi];
        var fInvUsed = fInv.recipientEmail && activatedEmails.indexOf(fInv.recipientEmail.toLowerCase()) !== -1;
        if (!fInvUsed) filteredInvites.push(fInv);
      }

      // Build combined items array: users first, then pending invites
      var allItems = [];
      for (var aui2 = 0; aui2 < allUsers.length; aui2++) {
        allItems.push({ type: 'user', data: allUsers[aui2] });
      }
      for (var fi2 = 0; fi2 < filteredInvites.length; fi2++) {
        allItems.push({ type: 'invite', data: filteredInvites[fi2] });
      }

      // Pagination
      var PAGE_SIZE = 5;
      var currentPage = 0;
      var totalPages = Math.ceil(allItems.length / PAGE_SIZE);

      function renderPage(page) {
        currentPage = page;
        var start = page * PAGE_SIZE;
        var end = Math.min(start + PAGE_SIZE, allItems.length);
        var pageItems = allItems.slice(start, end);

        var lh = '<div style="display:flex;flex-direction:column;gap:8px;">';
        for (var pi = 0; pi < pageItems.length; pi++) {
          var item = pageItems[pi];
          if (item.type === 'user') {
            var usr = item.data;
            var uFullName = (usr.firstName || '') + (usr.lastName ? ' ' + usr.lastName : '');
            var uInitials = ((usr.firstName || '')[0] || '').toUpperCase() + ((usr.lastName || '')[0] || '').toUpperCase();
            if (!uInitials.trim()) uInitials = '?';
            var uCreated = usr.createdAt ? new Date(usr.createdAt).toLocaleDateString() : '-';
            var uUsedAt = usr.usedAt ? new Date(usr.usedAt).toLocaleDateString() : '-';
            var uAvatarId = 'ref-avatar-u-' + page + '-' + pi;
            lh += '<div class="nn-invite-row" style="animation:nnSlideIn 0.3s ease ' + (pi * 0.05) + 's both;">' +
              '<img id="' + uAvatarId + '" data-avatar-input="' + escAttr((usr.firstName || '') + ' ' + (usr.email || '')) + '" style="width:38px;height:38px;border-radius:10px;flex-shrink:0;background:var(--nn-surface);" src="" />' +
              '<div style="flex:1;margin-left:14px;min-width:0;">' +
              '<div style="display:flex;align-items:center;gap:8px;">' +
              '<span style="font-size:13px;font-weight:600;color:var(--nn-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escHtml(uFullName) + '</span>' +
              '</div>' +
              '<div style="font-size:11px;color:var(--nn-text-dim);margin-top:3px;">' + escHtml(usr.email || '') + '</div>' +
              '<div style="font-size:10px;color:var(--nn-text-dim);margin-top:2px;opacity:0.7;">Joined: ' + uCreated + (usr.activated ? ' \u00B7 Activated: ' + uUsedAt : '') + '</div>' +
              '</div>' +
              '<div style="display:flex;align-items:center;gap:6px;flex-shrink:0;margin-left:12px;">' +
              (usr.activated ?
              '<span style="padding:5px 12px;font-size:11px;font-weight:600;background:color-mix(in srgb, var(--green,#40a02b) 12%, transparent);color:var(--green,#40a02b);border:1px solid color-mix(in srgb, var(--green,#40a02b) 25%, transparent);border-radius:6px;white-space:nowrap;">\u2713 Referral Active</span>' :
              '<span style="padding:5px 8px;font-size:10px;font-weight:600;background:color-mix(in srgb, var(--nn-text-dim) 10%, transparent);color:var(--nn-text-dim);border:1px solid color-mix(in srgb, var(--nn-text-dim) 20%, transparent);border-radius:6px;white-space:nowrap;">Pending</span>' +
              '<button class="nn-btn-resend resend-invite-btn" data-first="' + escAttr(usr.firstName || '') + '" data-last="' + escAttr(usr.lastName || '') + '" data-email="' + escAttr(usr.email || '') + '"><svg width="12" height="12" viewBox="0 0 24 24" fill="none"><path d="M17 1l4 4-4 4" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><path d="M3 11V9a4 4 0 0 1 4-4h14" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg> Resend</button>' +
              '<button class="nn-btn-delete delete-invite-btn" data-email="' + escAttr(usr.email || '') + '" data-name="' + escAttr(uFullName) + '"><svg width="12" height="12" viewBox="0 0 24 24" fill="none"><path d="M3 6h18M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg> Delete</button>') +
              '</div></div>';
          } else {
            var inv = item.data;
            var fullName = (inv.recipientFirst || '') + (inv.recipientLast ? ' ' + inv.recipientLast : '');
            var initials = ((inv.recipientFirst || '')[0] || '').toUpperCase() + ((inv.recipientLast || '')[0] || '').toUpperCase();
            if (!initials.trim()) initials = '?';
            var firstSent = inv.firstSent ? new Date(inv.firstSent).toLocaleDateString() : '-';
            var lastSent = inv.lastSent ? new Date(inv.lastSent).toLocaleDateString() : '-';
            var iAvatarId = 'ref-avatar-i-' + page + '-' + pi;
            lh += '<div class="nn-invite-row" style="animation:nnSlideIn 0.3s ease ' + (pi * 0.05) + 's both;">' +
              '<img id="' + iAvatarId + '" data-avatar-input="' + escAttr((inv.recipientFirst || '') + ' ' + (inv.recipientEmail || '')) + '" style="width:38px;height:38px;border-radius:10px;flex-shrink:0;background:var(--nn-surface);" src="" />' +
              '<div style="flex:1;margin-left:14px;min-width:0;">' +
              '<div style="display:flex;align-items:center;gap:8px;">' +
              '<span style="font-size:13px;font-weight:600;color:var(--nn-text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escHtml(fullName) + '</span>' +
              '<span style="font-size:10px;padding:2px 6px;background:color-mix(in srgb, var(--nn-accent) 12%, transparent);color:var(--nn-accent);border-radius:4px;font-weight:500;flex-shrink:0;">' + (inv.sendCount || 0) + ' send' + ((inv.sendCount || 0) !== 1 ? 's' : '') + '</span>' +
              '</div>' +
              '<div style="font-size:11px;color:var(--nn-text-dim);margin-top:3px;">' + escHtml(inv.recipientEmail || '') + '</div>' +
              '<div style="font-size:10px;color:var(--nn-text-dim);margin-top:2px;opacity:0.7;">First: ' + firstSent + ' \u00B7 Last: ' + lastSent + '</div>' +
              '</div>' +
              '<div style="display:flex;align-items:center;gap:6px;flex-shrink:0;margin-left:12px;">' +
              '<button class="nn-btn-resend resend-invite-btn" data-first="' + escAttr(inv.recipientFirst || '') + '" data-last="' + escAttr(inv.recipientLast || '') + '" data-email="' + escAttr(inv.recipientEmail || '') + '"><svg width="12" height="12" viewBox="0 0 24 24" fill="none"><path d="M17 1l4 4-4 4" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><path d="M3 11V9a4 4 0 0 1 4-4h14" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg> Resend</button>' +
              '<button class="nn-btn-delete delete-invite-btn" data-email="' + escAttr(inv.recipientEmail || '') + '" data-name="' + escAttr(fullName) + '"><svg width="12" height="12" viewBox="0 0 24 24" fill="none"><path d="M3 6h18M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg> Delete</button>' +
              '</div></div>';
          }
        }
        lh += '</div>';

        // Pagination controls
        if (totalPages > 1) {
          lh += '<div style="display:flex;align-items:center;justify-content:center;gap:8px;padding:16px 0 4px;border-top:1px solid color-mix(in srgb, var(--nn-text-dim) 15%, transparent);margin-top:12px;">';
          lh += '<button class="nn-page-btn" data-page="' + (page - 1) + '" ' + (page === 0 ? 'disabled style="opacity:0.4;cursor:default;padding:6px 10px;font-size:11px;font-weight:600;border:1px solid color-mix(in srgb, var(--nn-text-dim) 20%, transparent);background:transparent;color:var(--nn-text-dim);border-radius:6px;"' : 'style="padding:6px 10px;font-size:11px;font-weight:600;border:1px solid color-mix(in srgb, var(--nn-accent) 30%, transparent);background:transparent;color:var(--nn-accent);border-radius:6px;cursor:pointer;"') + '>\u2190 Prev</button>';
          lh += '<span style="font-size:11px;color:var(--nn-text-dim);font-weight:500;">' + (page + 1) + ' / ' + totalPages + '</span>';
          lh += '<button class="nn-page-btn" data-page="' + (page + 1) + '" ' + (page >= totalPages - 1 ? 'disabled style="opacity:0.4;cursor:default;padding:6px 10px;font-size:11px;font-weight:600;border:1px solid color-mix(in srgb, var(--nn-text-dim) 20%, transparent);background:transparent;color:var(--nn-text-dim);border-radius:6px;"' : 'style="padding:6px 10px;font-size:11px;font-weight:600;border:1px solid color-mix(in srgb, var(--nn-accent) 30%, transparent);background:transparent;color:var(--nn-accent);border-radius:6px;cursor:pointer;"') + '>Next \u2192</button>';
          lh += '</div>';
        }

        listEl.innerHTML = lh;
        var pageContainer = listEl.closest('.view-panel');
        if (pageContainer) pageContainer.scrollTop = 0;

        // Load monster avatars for all items on this page
        var avatarImgs = listEl.querySelectorAll('img[data-avatar-input]');
        for (var ai = 0; ai < avatarImgs.length; ai++) {
          (function(img) {
            var input = img.getAttribute('data-avatar-input');
            if (input && eapi()) {
              eapi().invoke('generate-avatar', { input: input }).then(function(result) {
                if (result && result.success && result.dataUri) {
                  img.src = result.dataUri;
                }
              });
            }
          })(avatarImgs[ai]);
        }

        // Wire pagination buttons
        var pageBtns = listEl.querySelectorAll('.nn-page-btn');
        for (var pbi = 0; pbi < pageBtns.length; pbi++) {
          pageBtns[pbi].addEventListener('click', function(e) {
            var btn = e.currentTarget;
            if (btn.disabled) return;
            var targetPage = parseInt(btn.getAttribute('data-page'), 10);
            if (targetPage >= 0 && targetPage < totalPages) {
              renderPage(targetPage);
            }
          });
        }

        // Wire resend buttons
        var resendBtns = listEl.querySelectorAll('.resend-invite-btn');
        for (var ri = 0; ri < resendBtns.length; ri++) {
          resendBtns[ri].addEventListener('click', function(e) {
            var btn = e.currentTarget;
            var rFirst = btn.getAttribute('data-first');
            var rLast = btn.getAttribute('data-last');
            var rEmail = btn.getAttribute('data-email');
            btn.disabled = true;
            btn.style.opacity = '0.6';
            btn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" style="animation:nnSpin 0.6s linear infinite"><path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg> Sending...';
            eapi().invoke('referral:send-invite', {
              senderRefCode: refCode, senderEmail: profile.email || '',
              recipientFirst: rFirst || '', recipientLast: rLast || undefined,
              recipientEmail: rEmail || ''
            }).then(function(res) {
              if (res && res.ok) {
                btn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none"><path d="M5 13l4 4L19 7" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg> Sent!';
                btn.style.opacity = '1';
                setTimeout(function() { showManageReferrals(refCode); }, 1500);
              } else {
                btn.disabled = false;
                btn.style.opacity = '1';
                btn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none"><path d="M17 1l4 4-4 4" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><path d="M3 11V9a4 4 0 0 1 4-4h14" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg> Resend';
                showThemedToast(res && res.error ? res.error : 'Failed to resend.', 'error');
              }
            }).catch(function() {
              btn.disabled = false;
              btn.style.opacity = '1';
              btn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none"><path d="M17 1l4 4-4 4" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><path d="M3 11V9a4 4 0 0 1 4-4h14" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg> Resend';
            });
          });
        }

        // Wire delete buttons
        var deleteBtns = listEl.querySelectorAll('.delete-invite-btn');
        for (var di = 0; di < deleteBtns.length; di++) {
          deleteBtns[di].addEventListener('click', function(e) {
            var btn = e.currentTarget;
            var dEmail = btn.getAttribute('data-email');
            var dName = btn.getAttribute('data-name');
            showThemedConfirm(
              'Remove Referral',
              'Remove ' + (dName || dEmail) + ' from your referrals? This action cannot be undone.',
              'Remove',
              'var(--red,#f38ba8)'
            ).then(function(confirmed) {
              if (!confirmed) return;
              btn.disabled = true;
              btn.style.opacity = '0.6';
              btn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" style="animation:nnSpin 0.6s linear infinite"><path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg> Removing...';
              // Call server withdraw endpoint then local delete
              eapi().invoke('referral:withdraw', { email: dEmail || '' }).then(function(wRes) {
                if (wRes && wRes.error) {
                  btn.disabled = false;
                  btn.style.opacity = '1';
                  btn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none"><path d="M3 6h18M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg> Delete';
                  showThemedToast(wRes.error, 'error');
                  return;
                }
                // Also store locally
                eapi().invoke('referral:delete-invite', {
                  senderRefCode: refCode,
                  recipientEmail: dEmail || ''
                }).then(function() {
                  showThemedToast((dName || dEmail) + ' has been removed', 'success');
                  var row = btn.closest('.nn-invite-row');
                  if (row) {
                    row.style.transition = 'all 0.3s ease';
                    row.style.opacity = '0';
                    row.style.transform = 'translateX(20px)';
                    row.style.maxHeight = row.offsetHeight + 'px';
                    setTimeout(function() {
                      row.style.maxHeight = '0';
                      row.style.padding = '0 16px';
                      row.style.margin = '0';
                      row.style.borderWidth = '0';
                      row.style.overflow = 'hidden';
                    }, 200);
                    setTimeout(function() { showManageReferrals(refCode); }, 600);
                  } else {
                    showManageReferrals(refCode);
                  }
                });
              }).catch(function(err) {
                btn.disabled = false;
                btn.style.opacity = '1';
                btn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none"><path d="M3 6h18M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg> Delete';
                showThemedToast(err && err.message ? err.message : 'Failed to remove.', 'error');
              });
            });
          });
        }
      }

      // Initial render
      renderPage(0);
    }
  }).catch(function(err) {
    var el = document.getElementById('referral-invites-list');
    if (el) el.innerHTML = '<div style="display:flex;align-items:center;gap:8px;color:var(--red,#f38ba8);padding:16px;background:color-mix(in srgb, var(--red,#f38ba8) 8%, transparent);border:1px solid color-mix(in srgb, var(--red,#f38ba8) 20%, transparent);border-radius:10px;"><svg width="18" height="18" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="10" stroke="currentColor" stroke-width="2"/><path d="M15 9l-6 6M9 9l6 6" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg> Failed to load: ' + escHtml(err && err.message ? err.message : String(err)) + '</div>';
  });
}
function showInvitationPanel() {
  // Remove any existing overlay first
  dismissInvitationPanel();

  var overlay = document.createElement('div');
  overlay.id = 'nn-invitation-overlay';
  overlay.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.85);display:flex;align-items:center;justify-content:center;z-index:99999;';

  var card = document.createElement('div');
  card.style.cssText = 'background:#1e1e2e;border:1px solid #45475a;border-radius:12px;padding:32px;max-width:420px;width:90%;color:#cdd6f4;font-family:inherit;';

  var title = document.createElement('h2');
  title.textContent = 'Enter Invitation Code';
  title.style.cssText = 'margin:0 0 8px 0;font-size:20px;color:#cdd6f4;';

  var desc = document.createElement('p');
  desc.textContent = 'Enter your invitation code to activate NeuroNest.';
  desc.style.cssText = 'margin:0 0 12px 0;font-size:14px;color:#bac2de;';

  var helpMsg = document.createElement('p');
  helpMsg.style.cssText = 'margin:0 0 20px 0;font-size:13px;color:#a6adc8;line-height:1.5;';
  var refProfile = {}; try { refProfile = JSON.parse(localStorage.getItem('neuronest-user-profile') || '{}'); } catch(_e) {}
  var downloadRef = refProfile.referralCode ? '?ref=' + encodeURIComponent(refProfile.referralCode) : '';
  helpMsg.innerHTML = 'Need an activation code? Get one for free at <a href="https://neuronest.cc/activate' + downloadRef + '" style="color:#89b4fa;text-decoration:underline;cursor:pointer;" target="_blank" rel="noopener noreferrer">neuronest.cc/activate</a>';

  // Open external links via shell if running in Electron
  helpMsg.querySelector('a').addEventListener('click', function(e) {
    e.preventDefault();
    if (eapi()) {
      eapi().invoke('shell:open-external', 'https://neuronest.cc/download');
    } else {
      window.open('https://neuronest.cc/download', '_blank');
    }
  });

  var input = document.createElement('input');
  input.type = 'text';
  input.placeholder = 'PQC-XXXXXXXX-YYYYYYYY';
  input.style.cssText = 'width:100%;padding:10px 12px;border-radius:8px;border:1px solid #45475a;background:#313244;color:#cdd6f4;font-size:14px;box-sizing:border-box;outline:none;';

  var errorArea = document.createElement('div');
  errorArea.style.cssText = 'margin-top:10px;font-size:13px;color:#f38ba8;display:none;';

  var btn = document.createElement('button');
  btn.textContent = 'Activate';
  btn.style.cssText = 'margin-top:16px;width:100%;padding:10px 0;border-radius:8px;border:none;background:#89b4fa;color:#1e1e2e;font-size:14px;font-weight:600;cursor:pointer;';

  btn.addEventListener('click', async function() {
    var code = input.value.trim();
    if (!code) {
      errorArea.textContent = 'Please enter an invitation code.';
      errorArea.style.display = 'block';
      return;
    }
    btn.disabled = true;
    btn.textContent = 'Activating...';
    btn.style.opacity = '0.7';
    btn.style.cursor = 'default';
    errorArea.style.display = 'none';

    try {
      var result = await eapi().invoke('license:fetch-by-code', { code: code });
      if (result && result.error) {
        errorArea.textContent = result.error;
        errorArea.style.display = 'block';
        btn.disabled = false;
        btn.textContent = 'Activate';
        btn.style.opacity = '1';
        btn.style.cursor = 'pointer';
        return;
      }
      // Check if the code is expired
      if (result && result.expiresAt) {
        var expDate = new Date(result.expiresAt);
        if (expDate.getTime() > 0 && expDate < new Date()) {
          errorArea.textContent = '\u23f0 This activation code has expired. Please get a new code from neuronest.cc/download.';
          errorArea.style.display = 'block';
          btn.disabled = false;
          btn.textContent = 'Activate';
          btn.style.opacity = '1';
          btn.style.cursor = 'pointer';
          return;
        }
      }
      // Mark the key as used
      var profile = {};
      try { profile = JSON.parse(localStorage.getItem('neuronest-user-profile') || '{}'); } catch (e) {}
      // Get appId from main process (reads/creates ~/.neuronest/app-id)
      var appIdResult = await eapi().invoke('license:get-app-id');
      var appId = (appIdResult && appIdResult.appId) ? appIdResult.appId : (profile.appId || '');
      var email = result.email || '';
      var feature = (result.features && result.features.length > 0) ? result.features[0] : undefined;
      var markResult = await eapi().invoke('license:mark-used', { code: result.invitationCode, hwid: result.hwid, appId: appId, email: email, feature: feature });
      // Store license key, plan, name, HWID, appId, and referral info in user profile.
      // Only overwrite licenseKey from the activation-flow result when the
      // existing slot does NOT already hold the Stripe-issued LK- bearer
      // token — `result.licenseKey` here is the 64-char PQC value, which
      // is not a proxy bearer token. Otherwise an activation refresh on a
      // paid user would clobber the Pro Mode bearer.
      var activationExistingIsProxyToken = typeof profile.licenseKey === 'string'
          && /^LK-[0-9a-f]{32}$/.test(profile.licenseKey);
      if (!activationExistingIsProxyToken) {
        profile.licenseKey = result.licenseKey;
      }
      // Mirror the NN_ proxy bearer token into the dedicated llmLicenseKey
      // slot if the worker minted one for this code (paid PQC users only;
      // community keys carry an empty string here).
      if (typeof result.llmLicenseKey === 'string'
          && /^NN_[0-9a-f]{32}$/.test(result.llmLicenseKey)) {
        profile.llmLicenseKey = result.llmLicenseKey;
      }
      console.log('[Activation] API result:', JSON.stringify({ plan: result.plan, features: result.features, licenseKey: result.licenseKey ? 'present' : 'missing', llmLicenseKey: result.llmLicenseKey ? 'present' : 'missing' }));
      // Determine plan: check result.plan, markResult.plan, features, or markResult.features
      var activatedPlan = result.plan || (markResult && markResult.plan) || 'community';
      if (activatedPlan === 'community' && result.features) {
        // Check features array for plan indicators
        var featStr = result.features.join(' ').toLowerCase();
        if (featStr.includes('enterprise') || featStr.includes('ent')) activatedPlan = 'enterprise';
        else if (featStr.includes('professional') || featStr.includes('pro')) activatedPlan = 'professional';
      }
      if (activatedPlan === 'community' && markResult && markResult.features) {
        var markFeatStr = (Array.isArray(markResult.features) ? markResult.features : []).join(' ').toLowerCase();
        if (markFeatStr.includes('enterprise') || markFeatStr.includes('ent')) activatedPlan = 'enterprise';
        else if (markFeatStr.includes('professional') || markFeatStr.includes('pro')) activatedPlan = 'professional';
      }
      profile.plan = activatedPlan;
      console.log('[Activation] Final plan:', profile.plan);
      profile.appId = appId;
      profile.email = email;
      if (markResult && markResult.referralCode) profile.referralCode = markResult.referralCode;
      if (markResult && markResult.referralUrl) profile.referralUrl = markResult.referralUrl;
      if (result.expiresAt) profile.licenseExpiry = result.expiresAt;
      if (result.firstName) profile.firstName = result.firstName;
      if (result.lastName) profile.lastName = result.lastName;
      if (result.firstName || result.lastName) {
        profile.name = ((result.firstName || '') + ' ' + (result.lastName || '')).trim();
      }
      if (result.hwid) profile.hwid = result.hwid;
      localStorage.setItem('neuronest-user-profile', JSON.stringify(profile));
      // Show referral code if available, then dismiss
      if (profile.referralCode) {
        showPostActivationReferral(profile.referralCode, profile.referralUrl || '', profile.email || '');
      } else {
        dismissInvitationPanel();
        // Reload to fully initialize the app after fresh activation
        setTimeout(function() { window.location.reload(); }, 500);
      }
    } catch (err) {
      errorArea.textContent = err && err.message ? err.message : 'Activation failed. Please try again.';
      errorArea.style.display = 'block';
      btn.disabled = false;
      btn.textContent = 'Activate';
      btn.style.opacity = '1';
      btn.style.cursor = 'pointer';
    }
  });

  card.appendChild(title);
  card.appendChild(desc);
  card.appendChild(helpMsg);
  card.appendChild(input);
  card.appendChild(errorArea);
  card.appendChild(btn);
  overlay.appendChild(card);
  document.body.appendChild(overlay);
  input.focus();
}

// ── Validation Failure Panel ──
// Requirements: 2.3, 2.4, 3.3

function dismissValidationFailurePanel() {
  var overlay = document.getElementById('nn-validation-failure-overlay');
  if (overlay) overlay.remove();
}

function showValidationFailurePanel() {
  dismissValidationFailurePanel();
  var overlay = document.createElement('div');
  overlay.id = 'nn-validation-failure-overlay';
  overlay.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.85);display:flex;align-items:center;justify-content:center;z-index:99999;';
  var card = document.createElement('div');
  card.style.cssText = 'background:#1e1e2e;border:1px solid #45475a;border-radius:12px;padding:32px;max-width:420px;width:90%;color:#cdd6f4;font-family:inherit;text-align:center;';
  var vfProfile = {};
  try { vfProfile = JSON.parse(localStorage.getItem('neuronest-user-profile') || '{}'); } catch(_e) {}
  var vfRefCode = vfProfile.referralCode || '';
  var vfDownloadUrl = 'https://neuronest.cc/download/' + (vfRefCode ? '?ref=' + encodeURIComponent(vfRefCode) : '');
  card.innerHTML = '<div style="font-size:48px;margin-bottom:16px;">\u23f0</div>' +
    '<h2 style="margin:0 0 12px;font-size:20px;color:#cdd6f4;">Activation Code Expired</h2>' +
    '<p style="margin:0 0 24px;font-size:14px;color:#bac2de;line-height:1.6;">Your activation code has expired. Get a new activation code from <a id="vf-download-link" href="#" style="color:#89b4fa;text-decoration:underline;cursor:pointer;">neuronest.cc/download</a> and enter it below.</p>' +
    '<button id="vf-new-code-btn" style="width:100%;padding:12px 0;border-radius:8px;border:none;background:#89b4fa;color:#1e1e2e;font-size:14px;font-weight:600;cursor:pointer;">\ud83d\udd11 Enter New Activation Code</button>';
  overlay.appendChild(card);
  document.body.appendChild(overlay);
  var vfDlLink = document.getElementById('vf-download-link');
  if (vfDlLink) vfDlLink.addEventListener('click', function(e) { e.preventDefault(); if (eapi()) eapi().invoke('shell:open-external', vfDownloadUrl); else window.open(vfDownloadUrl, '_blank'); });
  var vfCodeBtn = document.getElementById('vf-new-code-btn');
  if (vfCodeBtn) vfCodeBtn.addEventListener('click', function() { dismissValidationFailurePanel(); showInvitationPanel(); });
}


// ── License Email Mismatch Panel ──

function dismissLicenseEmailMismatchPanel() {
  var overlay = document.getElementById('nn-license-email-mismatch-overlay');
  if (overlay) overlay.remove();
}

function showLicenseEmailMismatchPanel(licenseEmail) {
  dismissLicenseEmailMismatchPanel();

  var overlay = document.createElement('div');
  overlay.id = 'nn-license-email-mismatch-overlay';
  overlay.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.85);display:flex;align-items:center;justify-content:center;z-index:99999;';

  var card = document.createElement('div');
  card.style.cssText = 'background:var(--bg-sidebar,#1e1e2e);border-radius:12px;padding:32px;max-width:440px;width:90%;color:#cdd6f4;font-family:inherit;text-align:center;';

  var icon = document.createElement('div');
  icon.textContent = '\uD83D\uDD12';
  icon.style.cssText = 'font-size:48px;margin-bottom:16px;';

  var title = document.createElement('h2');
  title.textContent = 'Email Mismatch';
  title.style.cssText = 'margin:0 0 12px 0;font-size:20px;color:#cdd6f4;';

  var desc = document.createElement('p');
  desc.style.cssText = 'margin:0 0 8px 0;font-size:14px;color:#a6adc8;line-height:1.6;';
  desc.textContent = 'The license key on this device is registered to:';

  var emailBadge = document.createElement('div');
  emailBadge.style.cssText = 'margin:8px 0 16px 0;padding:10px 16px;background:#313244;border:1px solid #45475a;border-radius:8px;font-size:15px;font-weight:600;color:#89b4fa;word-break:break-all;';
  emailBadge.textContent = licenseEmail || 'Unknown';

  var hint = document.createElement('p');
  hint.style.cssText = 'margin:0 0 24px 0;font-size:13px;color:#a6adc8;line-height:1.5;';
  hint.textContent = 'Please log out and sign in with the email address above to use this license.';

  var logoutBtn = document.createElement('button');
  logoutBtn.textContent = 'Logout';
  logoutBtn.style.cssText = 'width:100%;padding:10px 0;border-radius:8px;border:none;background:#f38ba8;color:#1e1e2e;font-size:14px;font-weight:600;cursor:pointer;';

  logoutBtn.addEventListener('click', function() {
    localStorage.removeItem('neuronest-credential-id');
    // Preserve plan and license data on logout
    try {
      var prof = JSON.parse(localStorage.getItem('neuronest-user-profile') || '{}');
      var preserved = { plan: prof.plan, licenseKey: prof.licenseKey, licenseExpiry: prof.licenseExpiry, hwid: prof.hwid, appId: prof.appId, referralCode: prof.referralCode, referralUrl: prof.referralUrl, email: prof.email, firstName: prof.firstName, lastName: prof.lastName };
      localStorage.setItem('neuronest-user-profile', JSON.stringify(preserved));
    } catch (_e) { localStorage.removeItem('neuronest-user-profile'); }
    updateLoginPill(false);
    dismissLicenseEmailMismatchPanel();
    if (eapi()) {
      eapi().invoke('auth-restart-server').catch(function() {});
    }
    showLoginView();
  });

  card.appendChild(icon);
  card.appendChild(title);
  card.appendChild(desc);
  card.appendChild(emailBadge);
  card.appendChild(hint);
  card.appendChild(logoutBtn);
  overlay.appendChild(card);
  document.body.appendChild(overlay);
}

// ── Startup License Check ──
// Requirements: 1.1, 2.1, 2.2, 2.3, 2.5, 2.6, 3.1, 4.1

function dismissOfflineBanner() {
  var banner = document.getElementById('nn-offline-license-banner');
  if (banner) banner.remove();
}

function showOfflineBanner() {
  dismissOfflineBanner();
  var banner = document.createElement('div');
  banner.id = 'nn-offline-license-banner';
  banner.style.cssText = 'position:fixed;top:0;left:0;width:100%;background:#f9e2af;color:#1e1e2e;font-size:13px;font-weight:600;padding:8px 40px 8px 16px;box-sizing:border-box;z-index:99998;text-align:center;';
  banner.textContent = 'License server unreachable \u2014 running in Community mode';

  var closeBtn = document.createElement('button');
  closeBtn.textContent = '\u2715';
  closeBtn.style.cssText = 'position:absolute;right:12px;top:50%;transform:translateY(-50%);background:none;border:none;color:#1e1e2e;font-size:16px;cursor:pointer;padding:0 4px;line-height:1;';
  closeBtn.addEventListener('click', function() {
    dismissOfflineBanner();
  });

  banner.appendChild(closeBtn);
  document.body.appendChild(banner);
}

async function checkLicenseOnStartup(retryCount) {
  if (retryCount === undefined) retryCount = 0;
  try {
    var stored = await eapi().invoke('license:get-stored');
    // Retry mark-used if it failed on a previous launch (fire-and-forget)
    if (stored && stored.markUsedPending === true) {
      try {
        var retryProfile = {};
        try { retryProfile = JSON.parse(localStorage.getItem('neuronest-user-profile') || '{}'); } catch (e) {}
        eapi().invoke('license:mark-used', { code: stored.invitationCode, hwid: stored.hwid, appId: retryProfile.appId || '', email: stored.email || '', feature: (stored.features && stored.features.length > 0) ? stored.features[0] : undefined });
      } catch (_e) {
        // Silently ignore — will retry on next launch
      }
    }
    if (!stored) {
      showInvitationPanel();
      return;
    }
    // Backfill referralCode: if stored license exists but no referral code, re-call markUsed to get it
    var bfProfile2 = {};
    try { bfProfile2 = JSON.parse(localStorage.getItem('neuronest-user-profile') || '{}'); } catch (_e) {}
    if (stored.referralCode) {
      // Already in SQLite — just sync to localStorage profile
      if (!bfProfile2.referralCode) {
        bfProfile2.referralCode = stored.referralCode;
        if (stored.referralUrl) bfProfile2.referralUrl = stored.referralUrl;
        if (stored.email && !bfProfile2.email) bfProfile2.email = stored.email;
        localStorage.setItem('neuronest-user-profile', JSON.stringify(bfProfile2));
      }
    } else if (stored.invitationCode && stored.hwid) {
      // No referral code in SQLite — re-call markUsed to fetch it from the server
      try {
        var refResult = await eapi().invoke('license:mark-used', {
          code: stored.invitationCode, hwid: stored.hwid,
          appId: bfProfile2.appId || '', email: stored.email || '',
          feature: (stored.features && stored.features.length > 0) ? stored.features[0] : undefined
        });
        if (refResult && refResult.referralCode) {
          bfProfile2.referralCode = refResult.referralCode;
          if (refResult.referralUrl) bfProfile2.referralUrl = refResult.referralUrl;
          if (stored.email && !bfProfile2.email) bfProfile2.email = stored.email;
          localStorage.setItem('neuronest-user-profile', JSON.stringify(bfProfile2));
        }
      } catch (_e) { /* best effort — will retry next launch */ }
    }
    var result = await eapi().invoke('license:validate');
    if (result && result.error) {
      showValidationFailurePanel();
      return;
    }
    if (result && result.valid && !result.offline) {
      // License valid and online — proceed normally
      return;
    }
    if (result && result.valid && result.offline) {
      // License valid but offline — community mode with notification
      showOfflineBanner();
      return;
    }
    if (result && !result.valid) {
      showValidationFailurePanel();
      return;
    }
  } catch (err) {
    // If the error is "No handler registered", retry after a delay (IPC race condition)
    var errMsg = (err && err.message) ? err.message : String(err);
    if (errMsg.indexOf('No handler registered') !== -1 && retryCount < 3) {
      console.warn('[License] IPC handler not ready, retrying in 1s... (attempt ' + (retryCount + 1) + '/3)');
      await new Promise(function(resolve) { setTimeout(resolve, 1000); });
      return checkLicenseOnStartup(retryCount + 1);
    }
    // On unexpected error after retries, show validation failure panel
    console.error('[License] Startup check failed:', errMsg);
    showValidationFailurePanel();
  }
}

