  // Run Scan button
  if (gateRunHtml) gateRunHtml.addEventListener('click', function() {
    if (!activeProjectId || !eapi()) return;
    var statusEl = document.getElementById('inspector-gate-status-html');
    // Show spinner
    gateRunHtml.innerHTML = '<span style="display:inline-block;width:12px;height:12px;border:2px solid rgba(255,255,255,0.3);border-top-color:#fff;border-radius:50%;animation:spin 0.6s linear infinite;"></span> Scanning...';
    gateRunHtml.style.opacity = '0.7';
    gateRunHtml.style.pointerEvents = 'none';
    if (statusEl) statusEl.innerHTML = '';

    // Start gate, then immediately end it (single-click scan)
    eapi().invoke('arch:gate-start', { projectId: activeProjectId }).then(function(gate) {
      if (!gate || gate.error) {
        gateRunHtml.innerHTML = '🔍 Run Scan';
        gateRunHtml.style.opacity = '1';
        gateRunHtml.style.pointerEvents = '';
        if (statusEl) statusEl.innerHTML = '<span style="color:var(--red);">Error: ' + (gate?.error || 'Unknown') + '</span>';
        return;
      }
      // Immediately end the gate to get the score
      eapi().invoke('arch:gate-end', { gateId: gate.id, projectId: activeProjectId }).then(function(result) {
        gateRunHtml.innerHTML = '🔍 Run Scan';
        gateRunHtml.style.opacity = '1';
        gateRunHtml.style.pointerEvents = '';
        if (statusEl && result && !result.error) {
          var score = result.finalScore || result.baselineScore || 0;
          var grade = score >= 8000 ? 'A' : score >= 6000 ? 'B' : score >= 4000 ? 'C' : score >= 2000 ? 'D' : 'F';
          var gradeColor = score >= 8000 ? 'var(--green)' : score >= 6000 ? 'var(--accent)' : score >= 4000 ? 'var(--yellow,#f9e2af)' : 'var(--red)';
          statusEl.innerHTML = '<div style="padding:8px 10px;background:var(--bg-input);border-radius:8px;border:1px solid ' + gradeColor + ';margin-top:4px;">' +
            '<div style="display:flex;align-items:center;justify-content:space-between;">' +
            '<span style="font-size:18px;font-weight:800;color:' + gradeColor + ';">' + grade + '</span>' +
            '<span style="font-size:12px;font-weight:700;color:var(--text-primary);">' + score + '<span style="font-size:9px;color:var(--text-dim);font-weight:400;">/10000</span></span>' +
            '</div>' +
            '<div style="margin-top:4px;height:4px;background:var(--border-color);border-radius:2px;overflow:hidden;"><div style="height:100%;width:' + (score / 100) + '%;background:' + gradeColor + ';border-radius:2px;"></div></div>' +
            '</div>';
        }
      }).catch(function() {
        gateRunHtml.innerHTML = '🔍 Run Scan';
        gateRunHtml.style.opacity = '1';
        gateRunHtml.style.pointerEvents = '';
      });
    }).catch(function() {
      gateRunHtml.innerHTML = '🔍 Run Scan';
      gateRunHtml.style.opacity = '1';
      gateRunHtml.style.pointerEvents = '';
    });
  });

  // Wire AI Readiness Score button
  var readinessRunBtn = document.getElementById('inspector-readiness-run');
