// ── Skills Panel ──
// Requirements: 10.1, 10.2, 10.3, 10.4, 10.5, 11.1, 11.2, 11.3, 16.5, 6.1, 6.3, 7.1, 7.2, 7.3, 15.1, 15.3

var skillsDebounceTimer = null;
var skillsSearchQuery = '';
var skillsFilterSource = '';
var skillsFilterScope = '';
var skillsFilterEnabled = '';
var skillsSort = 'name';
var selectedSkillId = null;

function showDesignTemplatesView() {
  var mc = $('#main-content');
  mc.innerHTML = '<div class="view-panel view-panel-wide" id="design-view">' +
    '<h2>\ud83c\udfa8 Design Templates</h2>' +
    '<div id="design-templates-area">' + showThinkingAnimation() + '</div>' +
    '</div>';

  eapi().invoke('skills:list', {}).then(function(allSkills) {
    allSkills = allSkills || [];
    var templates = allSkills.filter(function(s) { return s.category === 'design-template'; });

    var area = $('#design-templates-area');
    if (!area) return;

    if (templates.length === 0) {
      area.innerHTML = '<p style="color:var(--text-dim);font-size:13px;font-style:italic;">No design templates found.</p>';
      return;
    }

    // Sort alphabetically
    templates.sort(function(a, b) { return (a.name || '').localeCompare(b.name || ''); });

    // Reuse the existing renderSkillCard with sectionType='template' for Preview/Edit buttons
    var html = '<p style="font-size:12px;color:var(--text-dim);margin-bottom:12px;">' + templates.length + ' design template' + (templates.length !== 1 ? 's' : '') + ' available</p>';
    html += '<div class="skills-grid">';
    for (var i = 0; i < templates.length; i++) {
      html += renderSkillCard(templates[i], 'template');
    }
    html += '</div>';
    area.innerHTML = html;

    // Wire card click, toggle, and action handlers (same as skills view)
    var cards = area.querySelectorAll('.skill-card');
    for (var c = 0; c < cards.length; c++) {
      var cardId = cards[c].getAttribute('data-skill-id');
      if (cardId) cards[c].addEventListener('click', makeSkillCardClickHandler(cardId));
    }
    var toggles = area.querySelectorAll('.skill-toggle-btn');
    for (var t = 0; t < toggles.length; t++) {
      toggles[t].addEventListener('change', makeSkillToggleHandler(toggles[t]));
    }
    var actionBtns = area.querySelectorAll('.skill-action-btn');
    for (var a = 0; a < actionBtns.length; a++) {
      actionBtns[a].addEventListener('click', makeSkillActionHandler(actionBtns[a]));
    }
  }).catch(function(err) {
    var area = $('#design-templates-area');
    if (area) area.innerHTML = '<p style="color:var(--red);font-size:13px;">Failed to load design templates: ' + escHtml(String(err)) + '</p>';
  });
}

function showSkillsView() {
  var mc = $$('#main-content');
  mc.innerHTML = '<div class="view-panel view-panel-wide" id="skills-view">' +
    '<h2>🧩 Skills</h2>' +
    // Search & filter bar
    '<div class="skills-toolbar">' +
    '<input type="text" id="skills-search" class="skills-search-input" placeholder="Search skills..." />' +
    '<select id="skills-filter-source" class="skills-filter-select"><option value="">All Sources</option><option value="local">Local</option><option value="bundled">Bundled</option><option value="custom">Custom</option><option value="workspace">Workspace</option></select>' +
    '<select id="skills-filter-scope" class="skills-filter-select"><option value="">All Scopes</option><option value="global">Global</option><option value="workspace">Workspace</option><option value="project">Project</option><option value="agent">Agent</option></select>' +
    '<select id="skills-filter-enabled" class="skills-filter-select"><option value="">All Status</option><option value="true">Enabled</option><option value="false">Disabled</option></select>' +
    '<select id="skills-sort" class="skills-filter-select"><option value="name">Sort: Name</option><option value="category">Sort: Category</option><option value="source">Sort: Source</option><option value="updated">Sort: Updated</option></select>' +
    '</div>' +
    // Main content area — full width grid
    '<div class="skills-layout">' +
    '<div class="skills-list-area">' +
    '<div id="skills-installed-section"><h3>Installed Skills</h3><div id="skills-installed-grid" class="skills-grid">Loading...</div></div>' +
    '<div id="skills-catalog-section"><h3>Bundled Catalog</h3><div id="skills-catalog-grid" class="skills-grid">Loading...</div></div>' +
    '</div>' +
    '</div>' +
    '</div>';

  setupSkillsToolbar();
  loadSkillsData();
}

function setupSkillsToolbar() {
  var searchInput = $$('#skills-search');
  if (searchInput) {
    searchInput.value = skillsSearchQuery;
    searchInput.addEventListener('input', function() {
      if (skillsDebounceTimer) clearTimeout(skillsDebounceTimer);
      skillsDebounceTimer = setTimeout(function() {
        skillsSearchQuery = searchInput.value.trim();
        loadSkillsData();
      }, 200);
    });
  }
  var sourceFilter = $$('#skills-filter-source');
  if (sourceFilter) {
    sourceFilter.value = skillsFilterSource;
    sourceFilter.addEventListener('change', function() {
      skillsFilterSource = sourceFilter.value;
      loadSkillsData();
    });
  }
  var scopeFilter = $$('#skills-filter-scope');
  if (scopeFilter) {
    scopeFilter.value = skillsFilterScope;
    scopeFilter.addEventListener('change', function() {
      skillsFilterScope = scopeFilter.value;
      loadSkillsData();
    });
  }
  var enabledFilter = $$('#skills-filter-enabled');
  if (enabledFilter) {
    enabledFilter.value = skillsFilterEnabled;
    enabledFilter.addEventListener('change', function() {
      skillsFilterEnabled = enabledFilter.value;
      loadSkillsData();
    });
  }
  var sortSelect = $$('#skills-sort');
  if (sortSelect) {
    sortSelect.value = skillsSort;
    sortSelect.addEventListener('change', function() {
      skillsSort = sortSelect.value;
      loadSkillsData();
    });
  }
}

function loadSkillsData() {
  var filters = {};
  if (skillsFilterSource) filters.source = skillsFilterSource;
  if (skillsFilterScope) filters.scope = skillsFilterScope;
  if (skillsFilterEnabled === 'true') filters.enabled = true;
  if (skillsFilterEnabled === 'false') filters.enabled = false;

  Promise.all([
    eapi().invoke('skills:list', filters),
    eapi().invoke('skills:refreshCatalog', {})
  ]).then(function(results) {
    var allSkills = results[0] || [];
    var catalogResult = results[1] || {};
    var catalogEntries = catalogResult.entries || [];

    // Apply client-side search filter
    if (skillsSearchQuery) {
      var q = skillsSearchQuery.toLowerCase();
      allSkills = allSkills.filter(function(s) {
        return (s.name && s.name.toLowerCase().indexOf(q) !== -1) ||
          (s.description && s.description.toLowerCase().indexOf(q) !== -1) ||
          (s.category && s.category.toLowerCase().indexOf(q) !== -1) ||
          (s.tags && s.tags.join(',').toLowerCase().indexOf(q) !== -1);
      });
      catalogEntries = catalogEntries.filter(function(s) {
        return (s.name && s.name.toLowerCase().indexOf(q) !== -1) ||
          (s.description && s.description.toLowerCase().indexOf(q) !== -1) ||
          (s.category && s.category.toLowerCase().indexOf(q) !== -1) ||
          (s.tags && s.tags.join(',').toLowerCase().indexOf(q) !== -1);
      });
    }

    // Sort
    allSkills.sort(function(a, b) {
      if (skillsSort === 'name') return (a.name || '').localeCompare(b.name || '');
      if (skillsSort === 'category') return (a.category || '').localeCompare(b.category || '');
      if (skillsSort === 'source') return (a.source || '').localeCompare(b.source || '');
      if (skillsSort === 'updated') return (b.updatedAt || '').localeCompare(a.updatedAt || '');
      return 0;
    });

    // Build set of installed skill IDs to avoid duplicates in catalog section
    var installedIds = {};
    for (var k = 0; k < allSkills.length; k++) {
      installedIds[allSkills[k].id] = true;
    }

    // Split skills table entries into sections
    var installed = [];
    var templates = [];
    for (var i = 0; i < allSkills.length; i++) {
      var sk = allSkills[i];
      if (sk.category === 'design-template') {
        templates.push(sk);
      } else {
        installed.push(sk);
      }
    }

    // Catalog entries not already installed go to "Bundled Catalog"
    var catalog = [];
    for (var j = 0; j < catalogEntries.length; j++) {
      var ce = catalogEntries[j];
      if (!installedIds[ce.id]) {
        // Normalize catalog entry to look like a skill for rendering
        catalog.push({
          id: ce.id,
          name: ce.name,
          description: ce.description,
          category: ce.category || 'general',
          tags: ce.tags || [],
          source: 'bundled',
          version: ce.version || '1.0.0',
          enabled: true,
          installed: false,
          content: ce.content || ''
        });
      }
    }

    renderSkillsSection('skills-installed-grid', installed, 'installed');
    renderSkillsSection('skills-templates-grid', templates, 'template');
    renderSkillsSection('skills-catalog-grid', catalog, 'catalog');
  }).catch(function(err) {
    var grid = $$('#skills-installed-grid');
    if (grid) grid.innerHTML = '<p style="color:var(--text-dim);font-size:13px;">Failed to load skills: ' + escHtml(String(err)) + '</p>';
  });
}

function renderSkillsSection(containerId, skills, sectionType) {
  var container = $$('#' + containerId);
  if (!container) return;
  if (!skills || skills.length === 0) {
    container.innerHTML = '<p style="color:var(--text-dim);font-size:13px;font-style:italic;">No skills found</p>';
    return;
  }
  var html = '';
  for (var i = 0; i < skills.length; i++) {
    var sk = skills[i];
    html += renderSkillCard(sk, sectionType);
  }
  container.innerHTML = html;

  // Wire up card click handlers
  var cards = container.querySelectorAll('.skill-card');
  for (var j = 0; j < cards.length; j++) {
    cards[j].addEventListener('click', makeSkillCardClickHandler(cards[j].getAttribute('data-skill-id')));
  }

  // Wire up action buttons
  var toggleBtns = container.querySelectorAll('.skill-toggle-btn');
  for (var t = 0; t < toggleBtns.length; t++) {
    toggleBtns[t].addEventListener('click', makeSkillToggleHandler(toggleBtns[t]));
  }
  var actionBtns = container.querySelectorAll('.skill-action-btn');
  for (var a = 0; a < actionBtns.length; a++) {
    actionBtns[a].addEventListener('click', makeSkillActionHandler(actionBtns[a]));
  }
}

function renderSkillCard(skill, sectionType) {
  var sourceColors = { local: 'var(--green)', bundled: 'var(--accent)', custom: 'var(--yellow)', workspace: 'var(--text-secondary)' };
  var sourceColor = sourceColors[skill.source] || 'var(--text-dim)';
  var isSelected = selectedSkillId === skill.id;

  var html = '<div class="skill-card' + (isSelected ? ' skill-card-selected' : '') + '" data-skill-id="' + escHtml(skill.id) + '">';
  html += '<div class="skill-card-header">';
  html += '<span class="skill-card-name">' + escHtml(skill.name || skill.id) + '</span>';
  html += '<label class="skill-toggle" onclick="event.stopPropagation()"><input type="checkbox" class="skill-toggle-btn" data-skill-id="' + escHtml(skill.id) + '"' + (skill.enabled ? ' checked' : '') + ' /><span class="skill-toggle-slider"></span></label>';
  html += '</div>';
  html += '<div class="skill-card-meta">';
  if (skill.category) html += '<span class="skill-badge skill-badge-category">' + escHtml(skill.category) + '</span>';
  html += '<span class="skill-badge" style="color:' + sourceColor + ';border-color:' + sourceColor + ';">' + escHtml(skill.source || 'unknown') + '</span>';
  html += '</div>';
  if (skill.description) {
    html += '<div class="skill-card-desc">' + escHtml(skill.description.length > 120 ? skill.description.substring(0, 120) + '...' : skill.description) + '</div>';
  }
  html += '<div class="skill-card-actions">';
  if (sectionType === 'catalog') {
    html += '<button class="skill-action-btn prov-btn" data-action="install" data-skill-id="' + escHtml(skill.id) + '" onclick="event.stopPropagation()">Install</button>';
  } else if (sectionType === 'template') {
    html += '<button class="skill-action-btn prov-btn" data-action="preview" data-skill-id="' + escHtml(skill.id) + '" onclick="event.stopPropagation()">👁 Preview</button>';
    html += '<button class="skill-action-btn prov-btn" data-action="edit" data-skill-id="' + escHtml(skill.id) + '" onclick="event.stopPropagation()">Edit</button>';
  } else {
    html += '<button class="skill-action-btn prov-btn" data-action="edit" data-skill-id="' + escHtml(skill.id) + '" onclick="event.stopPropagation()">Edit</button>';
    if (skill.source !== 'bundled') {
      html += '<button class="skill-action-btn prov-btn prov-del" data-action="remove" data-skill-id="' + escHtml(skill.id) + '" onclick="event.stopPropagation()">Remove</button>';
    }
  }
  html += '</div>';
  html += '</div>';
  return html;
}

function makeSkillCardClickHandler(skillId) {
  return function(e) {
    e.stopPropagation();
    selectedSkillId = skillId;
    // Highlight selected card
    var allCards = document.querySelectorAll('.skill-card');
    for (var i = 0; i < allCards.length; i++) {
      allCards[i].classList.remove('skill-card-selected');
      if (allCards[i].getAttribute('data-skill-id') === skillId) {
        allCards[i].classList.add('skill-card-selected');
      }
    }
    showSkillDetail(skillId);
  };
}

function makeSkillToggleHandler(btn) {
  return function(e) {
    e.stopPropagation();
    var skillId = btn.getAttribute('data-skill-id');
    var enabled = btn.checked;
    var channel = enabled ? 'skills:enable' : 'skills:disable';
    eapi().invoke(channel, { id: skillId }).then(function() {
      // Refresh detail if this skill is selected
      if (selectedSkillId === skillId) showSkillDetail(skillId);
    }).catch(function(err) {
      console.error('[Skills] Toggle error:', err);
      btn.checked = !enabled; // revert
    });
  };
}

function makeSkillActionHandler(btn) {
  return function(e) {
    e.stopPropagation();
    var action = btn.getAttribute('data-action');
    var skillId = btn.getAttribute('data-skill-id');
    if (action === 'install') {
      btn.disabled = true;
      btn.textContent = 'Installing...';
      eapi().invoke('skills:install', { id: skillId }).then(function() {
        loadSkillsData();
      }).catch(function(err) {
        btn.disabled = false;
        btn.textContent = 'Install';
        console.error('[Skills] Install error:', err);
      });
    } else if (action === 'remove') {
      eapi().invoke('skills:remove', { id: skillId }).then(function() {
        if (selectedSkillId === skillId) {
          selectedSkillId = null;
        }
        loadSkillsData();
      }).catch(function(err) {
        console.error('[Skills] Remove error:', err);
      });
    } else if (action === 'test') {
      selectedSkillId = skillId;
      showSkillDetail(skillId);
    } else if (action === 'edit') {
      showSkillEditForm(skillId);
    } else if (action === 'preview') {
      showSkillPreview(skillId);
    }
  };
}

function showSkillDetail(skillId) {
  // Remove any existing modal
  var existing = document.querySelector('.skill-modal-overlay');
  if (existing) existing.remove();

  // Create modal overlay
  var overlay = document.createElement('div');
  overlay.className = 'skill-modal-overlay';
  overlay.innerHTML = '<div class="skill-modal"><button class="skill-modal-close">&times;</button><div id="skill-modal-body" style="color:var(--text-dim);">Loading...</div></div>';
  document.body.appendChild(overlay);

  // Close on overlay click or close button
  overlay.addEventListener('click', function(e) { if (e.target === overlay) overlay.remove(); });
  overlay.querySelector('.skill-modal-close').addEventListener('click', function() { overlay.remove(); });

  var body = overlay.querySelector('#skill-modal-body');

  eapi().invoke('skills:get', { id: skillId }).then(function(skill) {
    if (!skill || skill.error) {
      body.innerHTML = '<p style="color:var(--text-dim);">Skill not found</p>';
      return;
    }
    var tagBadges = '';
    if (skill.tags && skill.tags.length > 0) {
      for (var t = 0; t < skill.tags.length; t++) {
        tagBadges += '<span class="skill-badge" style="font-size:10px;">' + escHtml(skill.tags[t]) + '</span> ';
      }
    }

    var html = '<div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:16px;">';
    html += '<div>';
    html += '<h3 style="margin:0 0 6px 0;font-size:18px;">' + escHtml(skill.name || skill.id) + '</h3>';
    html += '<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;">';
    html += '<span class="skill-badge skill-badge-category">' + escHtml(skill.category || 'general') + '</span>';
    html += '<span class="skill-badge" style="color:var(--accent);border-color:var(--accent);">' + escHtml(skill.source || 'bundled') + '</span>';
    html += '<span class="skill-badge">' + escHtml(skill.scope || 'project') + '</span>';
    html += '<span class="skill-badge">v' + escHtml(skill.version || '1.0.0') + '</span>';
    html += '</div>';
    html += '</div>';
    html += '<button class="setting-btn" id="skill-detail-edit-btn" style="flex-shrink:0;">✏️ Edit</button>';
    html += '</div>';

    if (skill.description) {
      html += '<p style="font-size:13px;color:var(--text-secondary);margin:0 0 12px 0;line-height:1.6;">' + escHtml(skill.description) + '</p>';
    }
    if (tagBadges) {
      html += '<div style="margin-bottom:14px;">' + tagBadges + '</div>';
    }

    // Design prompt / skill content
    if (skill.content) {
      html += '<div style="border-top:1px solid var(--border-color);padding-top:14px;">';
      html += '<h4 style="font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;color:var(--text-dim);margin-bottom:8px;">Design Prompt</h4>';
      html += '<pre style="font-size:12px;line-height:1.6;color:var(--text-secondary);white-space:pre-wrap;word-wrap:break-word;max-height:400px;overflow-y:auto;background:var(--bg-input);border:1px solid var(--border-color);border-radius:10px;padding:14px;">' + escHtml(skill.content) + '</pre>';
      html += '</div>';
    }

    body.innerHTML = html;

    // Wire edit button
    var editBtn = $$('#skill-detail-edit-btn');
    if (editBtn) {
      editBtn.addEventListener('click', function() {
        overlay.remove();
        showSkillEditForm(skillId);
      });
    }
  }).catch(function(err) {
    body.innerHTML = '<p style="color:var(--red);">Error: ' + escHtml(String(err)) + '</p>';
  });
}

function showSkillPreview(skillId) {
  var existing = document.querySelector('.skill-modal-overlay');
  if (existing) existing.remove();

  var overlay = document.createElement('div');
  overlay.className = 'skill-modal-overlay';
  overlay.innerHTML = '<div class="skill-modal" style="width:1100px;max-width:96vw;height:70vh;padding:0;overflow:hidden;display:flex;flex-direction:column;">' +
    '<div style="display:flex;align-items:center;justify-content:space-between;padding:10px 16px;background:var(--bg-sidebar);border-bottom:1px solid var(--border-color);flex-shrink:0;">' +
    '<span id="skill-preview-title" style="font-size:13px;font-weight:600;color:var(--text-primary);">Preview</span>' +
    '<button class="skill-modal-close" style="position:static;background:none;border:none;color:var(--text-dim);font-size:18px;cursor:pointer;padding:4px 8px;border-radius:6px;line-height:1;">&times;</button>' +
    '</div>' +
    '<div id="skill-preview-frame" style="flex:1;min-height:0;overflow:hidden;"></div>' +
    '</div>';
  document.body.appendChild(overlay);

  overlay.addEventListener('click', function(e) { if (e.target === overlay) overlay.remove(); });
  overlay.querySelector('.skill-modal-close').addEventListener('click', function() { overlay.remove(); });

  var frame = overlay.querySelector('#skill-preview-frame');
  var titleEl = overlay.querySelector('#skill-preview-title');

  eapi().invoke('skills:get', { id: skillId }).then(function(skill) {
    if (!skill) {
      frame.innerHTML = '<p style="padding:24px;color:var(--text-dim);">Skill not found</p>';
      return;
    }

    if (titleEl) titleEl.textContent = skill.name || 'Preview';

    var previewHtml = (skill.metadata && skill.metadata.previewHtml) ? skill.metadata.previewHtml : null;

    // If no stored preview, generate one from the DESIGN.md content
    if (!previewHtml && skill.content) {
      previewHtml = generatePreviewFromContent(skill.content, skill.name || 'Design Template');
    }

    if (!previewHtml) {
      frame.innerHTML = '<p style="padding:24px;color:var(--text-dim);">No preview available</p>';
      return;
    }

    var templateName = skill.name || '';
    if (templateName) {
      previewHtml = previewHtml.replace(/<title>[^<]*<\/title>/i, '<title>' + templateName + ' — Preview</title>');
    }

    var iframe = document.createElement('iframe');
    iframe.style.cssText = 'width:100%;height:100%;border:none;';
    frame.innerHTML = '';
    frame.appendChild(iframe);
    iframe.contentDocument.open();
    iframe.contentDocument.write(previewHtml);
    iframe.contentDocument.close();
  }).catch(function(err) {
    frame.innerHTML = '<p style="padding:24px;color:var(--red);">Error: ' + escHtml(String(err)) + '</p>';
  });
}

function generatePreviewFromContent(content, name) {
  // Extract colors from DESIGN.md content
  var allColors = content.match(/#[0-9A-Fa-f]{6}/g) || [];
  var uniqueColors = [];
  var seen = {};
  for (var i = 0; i < allColors.length && uniqueColors.length < 16; i++) {
    var c = allColors[i].toLowerCase();
    if (!seen[c]) { seen[c] = true; uniqueColors.push(allColors[i]); }
  }

  // Try to extract semantic colors
  var bg = '#1a1a2e', surface = '#16213e', primary = '#89b4fa', text = '#e4e4e7', dim = '#9ca3af', border = '#2a2a3e';
  var m;
  m = content.match(/(?:background|bg)[^#\n]{0,40}(#[0-9A-Fa-f]{6})/i); if (m) bg = m[1];
  m = content.match(/(?:surface|card)[^#\n]{0,40}(#[0-9A-Fa-f]{6})/i); if (m) surface = m[1];
  m = content.match(/(?:primary|accent|brand)[^#\n]{0,40}(#[0-9A-Fa-f]{6})/i); if (m) primary = m[1];
  m = content.match(/(?:text|foreground|heading)[^#\n]{0,30}(#[0-9A-Fa-f]{6})/i); if (m) text = m[1];
  m = content.match(/(?:secondary|muted|dim|subtle)[^#\n]{0,30}(#[0-9A-Fa-f]{6})/i); if (m) dim = m[1];
  m = content.match(/(?:border|divider|separator)[^#\n]{0,30}(#[0-9A-Fa-f]{6})/i); if (m) border = m[1];

  // Extract font
  var font = 'system-ui, -apple-system, sans-serif';
  m = content.match(/(?:font.?family|typeface)[^:\n]*:\s*([^\n;]{5,60})/i);
  if (m) font = m[1].replace(/[`*]/g, '').trim();

  // Extract border radius
  var radius = '8px';
  m = content.match(/(?:border.?radius|corner)[^:\n]*:\s*(\d+px)/i);
  if (m) radius = m[1];

  var h = '<!DOCTYPE html><html><head><meta charset="utf-8"><title>' + name + '</title><style>';
  h += '*{margin:0;padding:0;box-sizing:border-box}';
  h += 'body{background:' + bg + ';color:' + text + ';font-family:' + font + ';padding:0}';
  h += '.nav{display:flex;align-items:center;justify-content:space-between;padding:14px 32px;background:' + surface + ';border-bottom:1px solid ' + border + '}';
  h += '.nav-brand{font-size:14px;font-weight:700;color:' + primary + '}';
  h += '.nav-links{display:flex;gap:20px;list-style:none}.nav-links a{font-size:13px;color:' + dim + ';text-decoration:none}.nav-links a:first-child{color:' + primary + ';font-weight:600}';
  h += '.hero{padding:64px 32px;text-align:center}';
  h += '.hero h1{font-size:40px;font-weight:700;margin-bottom:12px;color:' + text + '}';
  h += '.hero p{font-size:16px;color:' + dim + ';max-width:560px;margin:0 auto 24px;line-height:1.6}';
  h += '.section{padding:40px 32px}.section-title{font-size:10px;text-transform:uppercase;letter-spacing:1.5px;color:' + dim + ';margin-bottom:16px;font-weight:600}';
  h += '.color-grid{display:flex;gap:10px;flex-wrap:wrap}';
  h += '.swatch{width:72px;height:52px;border-radius:' + radius + ';display:flex;align-items:flex-end;justify-content:center;padding:4px;font-size:9px;border:1px solid ' + border + '}';
  h += '.type-sample h2{font-size:28px;margin-bottom:8px}.type-sample h3{font-size:20px;margin-bottom:6px}.type-sample p{font-size:14px;line-height:1.7;color:' + dim + ';max-width:480px}';
  h += '.btn-row{display:flex;gap:10px;flex-wrap:wrap;margin-top:8px}';
  h += '.btn-p{background:' + primary + ';color:' + bg + ';border:none;padding:10px 22px;border-radius:' + radius + ';font-size:13px;font-weight:600;cursor:pointer}';
  h += '.btn-s{background:transparent;color:' + primary + ';border:1px solid ' + primary + ';padding:10px 22px;border-radius:' + radius + ';font-size:13px;font-weight:600;cursor:pointer}';
  h += '.btn-g{background:transparent;color:' + dim + ';border:1px solid ' + border + ';padding:10px 22px;border-radius:' + radius + ';font-size:13px;cursor:pointer}';
  h += '.card-row{display:flex;gap:14px;flex-wrap:wrap;margin-top:8px}';
  h += '.card{background:' + surface + ';border:1px solid ' + border + ';border-radius:' + radius + ';padding:20px;width:220px}';
  h += '.card h4{font-size:14px;margin-bottom:6px}.card p{font-size:12px;color:' + dim + ';line-height:1.5}';
  h += '.form-row{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-top:8px}';
  h += '.input-s{background:' + surface + ';border:1px solid ' + border + ';border-radius:' + radius + ';padding:10px 14px;color:' + text + ';font-size:13px;width:260px;outline:none;font-family:inherit}';
  h += '.badge{display:inline-block;padding:3px 10px;border-radius:20px;font-size:11px;font-weight:600;background:' + primary + '22;color:' + primary + ';border:1px solid ' + primary + '44;margin-right:6px}';
  h += 'footer{padding:20px 32px;text-align:center;font-size:11px;color:' + dim + ';border-top:1px solid ' + border + '}';
  h += '</style></head><body>';
  h += '<nav class="nav"><span class="nav-brand">🧠 NeuroNest</span><ul class="nav-links"><li><a href="#">Colors</a></li><li><a href="#">Typography</a></li><li><a href="#">Buttons</a></li><li><a href="#">Cards</a></li><li><a href="#">Forms</a></li></ul></nav>';
  h += '<section class="hero"><h1>' + name + '</h1><p>A design token catalog generated by 🧠 NeuroNest. Colors, typography, buttons, cards, and form elements.</p></section>';
  h += '<section class="section"><div class="section-title">Color Palette</div><div class="color-grid">';
  var labels = ['Background', 'Surface', 'Primary', 'Text', 'Muted', 'Border'];
  var vals = [bg, surface, primary, text, dim, border];
  for (var ci = 0; ci < vals.length; ci++) {
    h += '<div class="swatch" style="background:' + vals[ci] + ';color:' + (ci < 3 ? dim : bg) + ';">' + labels[ci] + '<br>' + vals[ci] + '</div>';
  }
  for (var ui = 0; ui < uniqueColors.length && ui < 10; ui++) {
    if (vals.indexOf(uniqueColors[ui]) === -1) {
      h += '<div class="swatch" style="background:' + uniqueColors[ui] + ';">' + uniqueColors[ui] + '</div>';
    }
  }
  h += '</div></section>';
  h += '<section class="section"><div class="section-title">Typography</div><div class="type-sample"><h2>Heading Two</h2><h3>Heading Three</h3><p>Body text sample showing the default paragraph style with proper line height and color treatment for comfortable reading.</p></div></section>';
  h += '<section class="section"><div class="section-title">Buttons</div><div class="btn-row"><button class="btn-p">Primary</button><button class="btn-s">Secondary</button><button class="btn-g">Ghost</button></div></section>';
  h += '<section class="section"><div class="section-title">Cards</div><div class="card-row"><div class="card"><h4>Feature Card</h4><p>Surface color, border treatment, and text hierarchy in a contained component.</p></div><div class="card"><h4>Dashboard Widget</h4><p>Data visualization placeholder with metric display and status indicators.</p></div><div class="card"><h4>Settings Panel</h4><p>Configuration controls with form elements and action buttons.</p></div></div></section>';
  h += '<section class="section"><div class="section-title">Form Elements</div><div class="form-row"><input class="input-s" placeholder="Text input..." /><span class="badge">Badge</span><span class="badge">Tag</span><span class="badge">Label</span></div></section>';
  h += '<footer>Design token catalog generated by 🧠 NeuroNest</footer>';
  h += '</body></html>';
  return h;
}

function loadSkillExecLog(skillId) {
  var logEl = $$('#skill-exec-log');
  if (!logEl) return;
  // Fetch skill data which includes execution history
  eapi().invoke('skills:get', { id: skillId }).then(function(skill) {
    if (!skill || !skill.executions || skill.executions.length === 0) {
      logEl.innerHTML = '<p style="color:var(--text-dim);font-size:12px;font-style:italic;">No executions yet</p>';
      return;
    }
    var html = '<table class="skill-log-table"><thead><tr><th>Time</th><th>Mode</th><th>Status</th><th>Duration</th></tr></thead><tbody>';
    for (var i = 0; i < skill.executions.length; i++) {
      var ex = skill.executions[i];
      var statusColor = ex.success ? 'var(--green)' : 'var(--red)';
      var statusText = ex.success ? '✅ Pass' : '❌ Fail';
      if (ex.test) statusText += ' (test)';
      html += '<tr>';
      html += '<td>' + escHtml(ex.started_at ? new Date(ex.started_at).toLocaleString() : '-') + '</td>';
      html += '<td>' + escHtml(ex.mode || '-') + '</td>';
      html += '<td style="color:' + statusColor + ';">' + statusText + '</td>';
      html += '<td>' + (ex.duration_ms != null ? ex.duration_ms + 'ms' : '-') + '</td>';
      html += '</tr>';
    }
    html += '</tbody></table>';
    logEl.innerHTML = html;
  }).catch(function() {
    logEl.innerHTML = '<p style="color:var(--text-dim);font-size:12px;">Could not load execution log</p>';
  });
}

function runSkillTest(skillId) {
  var inputEl = $$('#skill-test-input');
  var resultEl = $$('#skill-test-result');
  var runBtn = $$('#skill-test-run');
  if (!inputEl || !resultEl) return;

  var testInput = inputEl.value.trim() || '';
  resultEl.innerHTML = '<p style="color:var(--text-dim);font-size:12px;">Running test...</p>';
  if (runBtn) { runBtn.disabled = true; runBtn.textContent = 'Running...'; }

  eapi().invoke('skills:test', { id: skillId, input: testInput, projectDir: '.' }).then(function(result) {
    if (runBtn) { runBtn.disabled = false; runBtn.textContent = '▶ Run Test'; }
    if (!result) {
      resultEl.innerHTML = '<p style="color:var(--red);">No result returned</p>';
      return;
    }
    var html = '<div class="skill-test-output">';
    html += '<div class="stat-row"><span>Success</span><span class="value" style="color:' + (result.success ? 'var(--green)' : 'var(--red)') + ';">' + (result.success ? '✅ Yes' : '❌ No') + '</span></div>';
    html += '<div class="stat-row"><span>Duration</span><span class="value">' + (result.durationMs != null ? result.durationMs + 'ms' : '-') + '</span></div>';
    if (result.output) {
      html += '<div style="margin-top:6px;"><strong style="font-size:11px;color:var(--text-dim);">Output:</strong><pre style="font-size:12px;margin-top:4px;max-height:200px;overflow:auto;">' + escHtml(result.output) + '</pre></div>';
    }
    if (result.error) {
      html += '<div style="margin-top:6px;"><strong style="font-size:11px;color:var(--red);">Error:</strong><pre style="font-size:12px;color:var(--red);margin-top:4px;">' + escHtml(result.error) + '</pre></div>';
    }
    if (result.structured) {
      html += '<div style="margin-top:6px;"><strong style="font-size:11px;color:var(--text-dim);">Structured Output:</strong><pre style="font-size:12px;margin-top:4px;max-height:200px;overflow:auto;">' + escHtml(JSON.stringify(result.structured, null, 2)) + '</pre></div>';
    }
    if (result.logs && result.logs.length > 0) {
      html += '<div style="margin-top:6px;"><strong style="font-size:11px;color:var(--text-dim);">Logs:</strong><pre style="font-size:12px;margin-top:4px;max-height:150px;overflow:auto;">' + escHtml(result.logs.join('\n')) + '</pre></div>';
    }
    html += '</div>';
    resultEl.innerHTML = html;
    // Refresh execution log
    loadSkillExecLog(skillId);
  }).catch(function(err) {
    if (runBtn) { runBtn.disabled = false; runBtn.textContent = '▶ Run Test'; }
    resultEl.innerHTML = '<p style="color:var(--red);">Test failed: ' + escHtml(String(err)) + '</p>';
  });
}

function showSkillEditForm(skillId) {
  // Remove any existing modal
  var existing = document.querySelector('.skill-modal-overlay');
  if (existing) existing.remove();

  var overlay = document.createElement('div');
  overlay.className = 'skill-modal-overlay';
  overlay.innerHTML = '<div class="skill-modal"><button class="skill-modal-close">&times;</button><div id="skill-modal-body" style="color:var(--text-dim);">Loading...</div></div>';
  document.body.appendChild(overlay);

  overlay.addEventListener('click', function(e) { if (e.target === overlay) overlay.remove(); });
  overlay.querySelector('.skill-modal-close').addEventListener('click', function() { overlay.remove(); });

  var body = overlay.querySelector('#skill-modal-body');

  eapi().invoke('skills:get', { id: skillId }).then(function(skill) {
    if (!skill || skill.error) {
      body.innerHTML = '<p style="color:var(--text-dim);">Skill not found</p>';
      return;
    }
    var html = '<div class="skill-edit-form">';
    html += '<h3>Edit Skill</h3>';
    html += '<div class="form-row"><label>Name</label><input type="text" id="skill-edit-name" value="' + escHtml(skill.name || '') + '" /></div>';
    html += '<div class="form-row"><label>Description</label><input type="text" id="skill-edit-desc" value="' + escHtml(skill.description || '') + '" /></div>';
    html += '<div class="form-row"><label>Category</label><input type="text" id="skill-edit-category" value="' + escHtml(skill.category || '') + '" /></div>';
    html += '<div class="form-row"><label>Tags (comma-separated)</label><input type="text" id="skill-edit-tags" value="' + escHtml((skill.tags || []).join(', ')) + '" /></div>';
    html += '<div class="form-row"><label>Scope</label><select id="skill-edit-scope"><option value="global"' + (skill.scope === 'global' ? ' selected' : '') + '>Global</option><option value="workspace"' + (skill.scope === 'workspace' ? ' selected' : '') + '>Workspace</option><option value="project"' + (skill.scope === 'project' ? ' selected' : '') + '>Project</option><option value="agent"' + (skill.scope === 'agent' ? ' selected' : '') + '>Agent</option></select></div>';
    html += '<div class="form-row"><label>Content</label><textarea id="skill-edit-content" class="agent-prompt-textarea" style="min-height:200px;">' + escHtml(skill.content || '') + '</textarea></div>';
    html += '<div id="skill-edit-errors" style="color:var(--red);font-size:12px;margin-bottom:8px;"></div>';
    html += '<div class="form-actions">';
    html += '<button class="setting-btn" id="skill-edit-save">Save</button>';
    html += '<button class="prov-btn" id="skill-edit-cancel">Cancel</button>';
    html += '</div>';
    html += '</div>';
    body.innerHTML = html;

    // Wire save
    var saveBtn = $$('#skill-edit-save');
    if (saveBtn) {
      saveBtn.addEventListener('click', function() {
        var updated = {
          id: skillId,
          name: ($$('#skill-edit-name') || {}).value || '',
          description: ($$('#skill-edit-desc') || {}).value || '',
          category: ($$('#skill-edit-category') || {}).value || '',
          tags: (($$('#skill-edit-tags') || {}).value || '').split(',').map(function(t) { return t.trim(); }).filter(Boolean),
          scope: ($$('#skill-edit-scope') || {}).value || 'project',
          content: ($$('#skill-edit-content') || {}).value || ''
        };
        var errEl = $$('#skill-edit-errors');
        eapi().invoke('skills:update', updated).then(function(result) {
          if (result && result.error) {
            if (errEl) errEl.textContent = result.error;
            return;
          }
          overlay.remove();
          loadSkillsData();
        }).catch(function(err) {
          if (errEl) errEl.textContent = String(err);
        });
      });
    }

    // Wire cancel
    var cancelBtn = $$('#skill-edit-cancel');
    if (cancelBtn) {
      cancelBtn.addEventListener('click', function() {
        overlay.remove();
      });
    }
  }).catch(function(err) {
    body.innerHTML = '<p style="color:var(--red);">Error: ' + escHtml(String(err)) + '</p>';
  });
}


