function showGraphVisualizationFallback(graphData) {
  var vizEl = document.getElementById('graph-visualization');
  if (!vizEl) return;
  
  // Check if Cytoscape is available
  if (typeof window.cytoscape === 'undefined') {
    vizEl.innerHTML = '<div style="display:flex;align-items:center;justify-content:center;height:100%;color:var(--text-secondary);">' +
      '<div style="text-align:center;">' +
        '<div style="font-size:48px;margin-bottom:16px;">📊</div>' +
        '<div>Cytoscape.js not loaded</div>' +
        '<div style="font-size:12px;margin-top:8px;">Please check that all graph libraries are loaded</div>' +
      '</div>' +
    '</div>';
    return;
  }
  
  try {
    // Create basic Cytoscape visualization
    var elements = [];
    
    // Add nodes
    var nodeIds = new Set();
    graphData.nodes.forEach(function(node) {
      nodeIds.add(node.id);
      elements.push({
        data: {
          id: node.id,
          label: node.label,
          type: node.file_type || 'unknown'
        }
      });
    });
    
    // Add edges (only if both source and target nodes exist)
    graphData.edges.forEach(function(edge, index) {
      if (nodeIds.has(edge.source) && nodeIds.has(edge.target)) {
        elements.push({
          data: {
            id: 'edge-' + index,
            source: edge.source,
            target: edge.target,
            label: edge.relation
          }
        });
      } else {
        console.warn('[GraphViz] Skipping edge with invalid nodes:', edge.source, '->', edge.target);
      }
    });
    
    // Create Cytoscape instance
    var cy = window.cytoscape({
      container: vizEl,
      elements: elements,
      style: [
        {
          selector: 'node',
          style: {
            'background-color': '#3b82f6',
            'label': 'data(label)',
            'text-valign': 'center',
            'text-halign': 'center',
            'font-size': '12px',
            'color': '#ffffff',
            'text-outline-width': 2,
            'text-outline-color': '#1e40af',
            'width': 40,
            'height': 40
          }
        },
        {
          selector: 'edge',
          style: {
            'width': 2,
            'line-color': '#6b7280',
            'target-arrow-color': '#6b7280',
            'target-arrow-shape': 'triangle',
            'curve-style': 'bezier'
          }
        }
      ],
      layout: {
        name: 'cose',
        animate: true,
        fit: true,
        padding: 50,
        nodeRepulsion: 400000,
        nodeOverlap: 10,
        idealEdgeLength: 100,
        edgeElasticity: 100,
        nestingFactor: 5,
        gravity: 80,
        numIter: 1000,
        initialTemp: 200,
        coolingFactor: 0.95,
        minTemp: 1.0
      }
    });
    
    console.log('[NeuroNest] Graph visualization fallback created with', graphData.nodes.length, 'nodes');
    
  } catch (error) {
    console.error('[NeuroNest] Graph visualization fallback error:', error);
    vizEl.innerHTML = '<div style="display:flex;align-items:center;justify-content:center;height:100%;color:var(--text-secondary);">' +
      '<div style="text-align:center;">' +
        '<div style="font-size:48px;margin-bottom:16px;">⚠️</div>' +
        '<div>Failed to create graph visualization</div>' +
        '<div style="font-size:12px;margin-top:8px;">Error: ' + escHtml(error.message || 'Unknown error') + '</div>' +
      '</div>' +
    '</div>';
  }
}


// ── Runtime Environment ──

// Track which projects have active runtimes (exported for tests)
var activeRuntimes = new Set();

/**
 * Adds a "🕷 Runtime Debugger" or "■ Stop Debugger" menu option to a project's context menu.
 * @param projectEl - The menu container element (proj-menu div)
 * @param projectId - The project ID
 * @param projectPath - The project path (defaults to projectId if not available)
 */
function addRunMenuOption(projectEl, projectId, projectPath) {
  if (!projectEl || !projectId) return;
  var isRunning = activeRuntimes.has(projectId);
  var menuItem = document.createElement('div');
  menuItem.className = 'proj-menu-item';
  menuItem.setAttribute('data-action', isRunning ? 'runtime-stop-menu' : 'runtime-run');
  menuItem.textContent = isRunning ? '■ Stop Debugger' : '🕷 Runtime Debugger';
  // Insert before the delete (danger) item if present, otherwise append
  var dangerItem = projectEl.querySelector('.proj-menu-danger');
  if (dangerItem) {
    projectEl.insertBefore(menuItem, dangerItem);
  } else {
    projectEl.appendChild(menuItem);
  }
}

// ── Runtime View State ──
var _runtimeViewProjectId = null;
var _runtimeSelectedServiceId = null;
var _runtimeLogs = {}; // { serviceId: string[] }
var _runtimeLogListeners = null; // cleanup function for event listeners
var _runtimePreviewServiceId = null; // which service is shown in preview

/**
 * Show the Runtime View panel for a project.
 * Renders the full-panel view in #main-content with service list, log output,
 * controls, and live preview iframe.
 * @param projectId - The project ID to show the runtime view for
 */
function showRuntimeView(projectId) {
  console.log('[NeuroNest] showRuntimeView called for project:', projectId);
  _runtimeViewProjectId = projectId;
  _runtimeSelectedServiceId = null;
  _runtimePreviewServiceId = null;
  _runtimeLogs = {};

  _cleanupRuntimeListeners();

  var mc = $('#main-content');
  if (!mc) return;
  mc.innerHTML = '';

  // CSS
  var style = document.createElement('style');
  style.id = 'runtime-view-styles';
  style.textContent = '@keyframes runtime-pulse{0%,100%{opacity:1;}50%{opacity:0.3;}}' +
    '.rv-svc-panel{border:1px solid var(--border-color);border-radius:6px;margin-bottom:8px;overflow:hidden;background:var(--bg-secondary,#1a1a2e);}' +
    '.rv-svc-header{display:flex;align-items:center;justify-content:space-between;padding:6px 10px;background:var(--bg-input,#2a2a3e);cursor:pointer;user-select:none;}' +
    '.rv-svc-header:hover{background:var(--bg-hover,#333350);}' +
    '.rv-svc-log{min-height:80px;max-height:300px;overflow-y:auto;padding:8px 10px;font-family:SF Mono,Menlo,Consolas,monospace;font-size:11px;line-height:1.6;white-space:pre-wrap;word-break:break-all;color:#e0e0e0;background:#0d0d1a;border-top:1px solid var(--border-color);}' +
    '.rv-svc-controls{display:flex;gap:4px;}' +
    '.rv-ctrl{padding:2px 8px;border:1px solid var(--border-color);background:var(--bg-input);color:var(--text-primary);border-radius:3px;cursor:pointer;font-size:11px;}' +
    '.rv-ctrl:hover{background:var(--bg-hover,#333350);}' +
    '.rv-preview-btn{padding:2px 8px;border:1px solid var(--border-color);background:var(--bg-input);color:var(--text-primary);border-radius:3px;cursor:pointer;font-size:10px;margin-left:4px;}' +
    '.rv-preview-btn.active{background:var(--accent,#6c5ce7);color:#fff;border-color:var(--accent,#6c5ce7);}' +
    '.rv-divider{width:5px;cursor:col-resize;background:var(--border-color);flex-shrink:0;transition:background 0.15s;}' +
    '.rv-divider:hover,.rv-divider.dragging{background:var(--accent,#6c5ce7);}';
  if (!document.getElementById('runtime-view-styles')) {
    document.head.appendChild(style);
  }

  // Main container
  var container = document.createElement('div');
  container.id = 'runtime-view';
  container.style.cssText = 'display:flex;flex-direction:column;height:100%;background:var(--bg-primary);color:var(--text-primary);';

  // Header bar
  var header = document.createElement('div');
  header.style.cssText = 'display:flex;align-items:center;justify-content:space-between;padding:10px 16px;border-bottom:1px solid var(--border-color);flex-shrink:0;';
  header.innerHTML = '<div style="font-size:14px;font-weight:600;">🕷 Runtime Debugger: ' + escHtml(projectId) + '</div>' +
    '<div style="display:flex;gap:8px;">' +
    '<button id="rt-sandbox-btn" style="padding:5px 14px;border:1px solid var(--border-color);background:var(--surface-container);color:var(--text-primary);border-radius:6px;cursor:pointer;font-size:12px;font-weight:600;">🐳 Sandbox</button>' +
    '<button id="rt-run-doctor-btn" style="padding:5px 14px;border:1px solid var(--border-color);background:var(--accent);color:#fff;border-radius:6px;cursor:pointer;font-size:12px;font-weight:600;">🩺 Doctor</button>' +
    '<button id="rt-run-security-btn" style="padding:5px 14px;border:1px solid var(--border-color);background:var(--accent);color:#fff;border-radius:6px;cursor:pointer;font-size:12px;font-weight:600;">🔒 Security</button>' +
    '<button id="runtime-stop-all-btn" style="padding:5px 14px;border:none;background:var(--red,#e74c3c);color:#fff;border-radius:6px;cursor:pointer;font-size:12px;font-weight:600;">■ Stop All</button>' +
    '</div>';
  container.appendChild(header);

  // Body: left panel + divider + right panel
  var body = document.createElement('div');
  body.style.cssText = 'display:flex;flex:1;min-height:0;';

  // Left panel: 20% width, services with logs
  var leftPanel = document.createElement('div');
  leftPanel.id = 'runtime-services-panel';
  leftPanel.style.cssText = 'width:20%;min-width:0;overflow-y:auto;padding:8px;';
  body.appendChild(leftPanel);

  // Resizable divider
  var divider = document.createElement('div');
  divider.className = 'rv-divider';
  body.appendChild(divider);

  // Right panel: 80% width, preview iframe
  var rightPanel = document.createElement('div');
  rightPanel.id = 'runtime-preview-panel';
  rightPanel.style.cssText = 'flex:1;display:flex;flex-direction:column;min-width:200px;';

  var previewHeader = document.createElement('div');
  previewHeader.id = 'runtime-preview-header';
  previewHeader.style.cssText = 'padding:8px 12px;font-size:11px;font-weight:600;color:var(--text-secondary);border-bottom:1px solid var(--border-color);flex-shrink:0;';
  previewHeader.textContent = 'Live Preview';
  rightPanel.appendChild(previewHeader);

  var previewContainer = document.createElement('div');
  previewContainer.id = 'runtime-preview-container';
  previewContainer.style.cssText = 'flex:1;padding:8px;position:relative;min-height:0;';
  previewContainer.innerHTML = '<div id="rt-diagnostics-panel" style="display:none;margin-bottom:8px;max-height:250px;overflow-y:auto;"></div>' +
    '<div id="rt-security-panel" style="display:none;margin-bottom:8px;max-height:250px;overflow-y:auto;"></div>' +
    '<iframe id="runtime-preview-iframe" style="position:absolute;top:8px;left:8px;right:8px;bottom:8px;width:calc(100% - 16px);height:calc(100% - 16px);border:1px solid var(--border-color);border-radius:6px;background:#fff;" src="about:blank"></iframe>';
  rightPanel.appendChild(previewContainer);

  body.appendChild(rightPanel);
  container.appendChild(body);
  mc.appendChild(container);

  // ── Resizable divider logic ──
  (function() {
    var isDragging = false;
    divider.addEventListener('mousedown', function(e) {
      isDragging = true;
      divider.classList.add('dragging');
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
      // Disable pointer events on iframe during drag so it doesn't steal mouse
      var iframe = document.getElementById('runtime-preview-iframe');
      if (iframe) iframe.style.pointerEvents = 'none';
      e.preventDefault();
    });
    document.addEventListener('mousemove', function(e) {
      if (!isDragging) return;
      var bodyRect = body.getBoundingClientRect();
      var newLeftWidth = e.clientX - bodyRect.left;
      // Allow resizing from 60px to bodyWidth - 60px (virtually no restriction)
      if (newLeftWidth < 60) newLeftWidth = 60;
      if (newLeftWidth > bodyRect.width - 60) newLeftWidth = bodyRect.width - 60;
      leftPanel.style.width = newLeftWidth + 'px';
      leftPanel.style.minWidth = '0';
    });
    document.addEventListener('mouseup', function() {
      if (isDragging) {
        isDragging = false;
        divider.classList.remove('dragging');
        document.body.style.cursor = '';
        document.body.style.userSelect = '';
        var iframe = document.getElementById('runtime-preview-iframe');
        if (iframe) iframe.style.pointerEvents = '';
      }
    });
  })();

  // Wire stop-all button
  var stopAllBtn = document.getElementById('runtime-stop-all-btn');
  if (stopAllBtn) {
    stopAllBtn.addEventListener('click', function() {
      eapi().invoke('runtime-stop', { projectId: projectId }).then(function(result) {
        if (result && result.success) {
          activeRuntimes.delete(projectId);
          addMsg('assistant', '✅ Runtime stopped for project.', { label: 'Runtime' });
        }
      });
    });
  }

  // Wire Sandbox button
  var rtSandboxBtn = document.getElementById('rt-sandbox-btn');
  if (rtSandboxBtn) {
    rtSandboxBtn.addEventListener('click', function() {
      var diagPanel = document.getElementById('rt-diagnostics-panel');
      if (!diagPanel) return;
      var iframe = document.getElementById('runtime-preview-iframe');
      if (iframe) { iframe.style.position = 'relative'; iframe.style.top = '0'; iframe.style.left = '0'; iframe.style.right = '0'; iframe.style.bottom = '0'; iframe.style.width = '100%'; iframe.style.height = '400px'; }
      diagPanel.style.display = 'block';
      diagPanel.innerHTML = '<div style="display:flex;align-items:center;gap:8px;padding:10px 14px;background:var(--bg-input);border-radius:8px;border:1px solid var(--border-color);"><span style="display:inline-block;width:14px;height:14px;border:2px solid var(--accent);border-top-color:transparent;border-radius:50%;animation:spin 0.8s linear infinite;"></span><span style="font-size:12px;color:var(--text-secondary);">Checking Docker sandbox…</span></div>';

      eapi().invoke('sandbox:check').then(function(result) {
        var html = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;"><span style="font-size:13px;font-weight:600;color:var(--text-primary);">🐳 Docker Sandbox</span><button id="rt-sandbox-close" style="background:none;border:none;color:var(--text-dim);cursor:pointer;font-size:14px;">✕</button></div>';

        if (result && result.available) {
          html += '<div style="padding:10px;background:var(--bg-primary);border-radius:6px;border:1px solid var(--green);margin-bottom:8px;">';
          html += '<div style="font-size:12px;color:var(--green);font-weight:600;margin-bottom:4px;">✅ Docker Available</div>';
          html += '<div style="font-size:11px;color:var(--text-secondary);">Sandboxed execution is ready. Containers run with read-only filesystem, no-new-privileges, memory limits, and network isolation.</div>';
          html += '</div>';
          html += '<div style="display:flex;gap:8px;">';
          html += '<button id="rt-sandbox-create" style="padding:6px 14px;border:none;background:var(--accent);color:#fff;border-radius:6px;cursor:pointer;font-size:12px;font-weight:600;">Create Sandbox</button>';
          html += '<button id="rt-sandbox-list" style="padding:6px 14px;border:1px solid var(--border-color);background:var(--surface-container);color:var(--text-primary);border-radius:6px;cursor:pointer;font-size:12px;">List Sessions</button>';
          html += '</div>';
          html += '<div id="rt-sandbox-output" style="margin-top:8px;"></div>';
        } else {
          html += '<div style="padding:10px;background:var(--bg-primary);border-radius:6px;border:1px solid var(--yellow);margin-bottom:8px;">';
          html += '<div style="font-size:12px;color:var(--yellow);font-weight:600;margin-bottom:4px;">⚠️ Docker Not Available</div>';
          html += '<div style="font-size:11px;color:var(--text-secondary);">' + escHtml(result && result.error ? result.error : 'Install Docker Desktop to enable sandboxed execution.') + '</div>';
          html += '</div>';
          html += '<button id="rt-sandbox-install" style="padding:6px 14px;border:none;background:var(--accent);color:#fff;border-radius:6px;cursor:pointer;font-size:12px;font-weight:600;">Install Docker</button>';
          html += '<div id="rt-sandbox-install-status" style="margin-top:6px;"></div>';
        }

        diagPanel.innerHTML = html;

        var closeBtn = document.getElementById('rt-sandbox-close');
        if (closeBtn) closeBtn.addEventListener('click', function() { diagPanel.style.display = 'none'; });

        var installBtn2 = document.getElementById('rt-sandbox-install');
        if (installBtn2) {
          installBtn2.addEventListener('click', function() {
            _showDockerInstallConfirmation(function() {
              installBtn2.textContent = 'Installing…';
              installBtn2.disabled = true;
              installBtn2.style.opacity = '0.7';
              var statusEl = document.getElementById('rt-sandbox-install-status');
              eapi().invoke('sandbox:install-docker').then(function(res) {
                if (res && res.success) {
                  installBtn2.textContent = '✓ Installed';
                  installBtn2.style.background = 'var(--green)';
                  if (statusEl) statusEl.innerHTML = '<div style="font-size:11px;color:var(--green);">' + escHtml(res.message || 'Docker installed successfully') + '</div>';
                } else {
                  installBtn2.textContent = 'Failed';
                  installBtn2.style.background = 'var(--red)';
                  if (statusEl) statusEl.innerHTML = '<div style="font-size:11px;color:var(--red);">' + escHtml(res && res.error ? res.error : 'Installation failed') + '</div>';
                }
              }).catch(function(err) {
                installBtn2.textContent = 'Failed';
                installBtn2.style.background = 'var(--red)';
                if (statusEl) statusEl.innerHTML = '<div style="font-size:11px;color:var(--red);">' + escHtml(String(err)) + '</div>';
              });
            });
          });
        }

        var createBtn = document.getElementById('rt-sandbox-create');
        if (createBtn) {
          createBtn.addEventListener('click', function() {
            var output = document.getElementById('rt-sandbox-output');
            if (output) output.innerHTML = '<div style="font-size:11px;color:var(--text-secondary);padding:6px;">Creating sandbox…</div>';
            eapi().invoke('sandbox:create', { projectId: projectId, projectPath: projectId }).then(function(res) {
              if (res && res.success) {
                if (output) output.innerHTML = '<div style="font-size:11px;color:var(--green);padding:6px;">✅ Sandbox created: ' + escHtml(res.session.id) + ' (port ' + res.session.hostPort + ')</div>';
              } else {
                if (output) output.innerHTML = '<div style="font-size:11px;color:var(--red);padding:6px;">❌ ' + escHtml(res && res.error ? res.error : 'Failed') + '</div>';
              }
            }).catch(function(err) {
              if (output) output.innerHTML = '<div style="font-size:11px;color:var(--red);padding:6px;">❌ ' + escHtml(String(err)) + '</div>';
            });
          });
        }

        var listBtn = document.getElementById('rt-sandbox-list');
        if (listBtn) {
          listBtn.addEventListener('click', function() {
            var output = document.getElementById('rt-sandbox-output');
            eapi().invoke('sandbox:list').then(function(res) {
              if (res && res.success && res.sessions && res.sessions.length > 0) {
                var lhtml = '<div style="font-size:11px;color:var(--text-secondary);padding:6px;">';
                for (var si = 0; si < res.sessions.length; si++) {
                  var sess = res.sessions[si];
                  lhtml += '<div style="padding:4px 0;border-bottom:1px solid var(--border-color);">🐳 ' + escHtml(sess.id) + ' — port ' + sess.hostPort + ' — ' + sess.status + '</div>';
                }
                lhtml += '</div>';
                if (output) output.innerHTML = lhtml;
              } else {
                if (output) output.innerHTML = '<div style="font-size:11px;color:var(--text-dim);padding:6px;">No active sandbox sessions.</div>';
              }
            }).catch(function() {
              if (output) output.innerHTML = '<div style="font-size:11px;color:var(--text-dim);padding:6px;">No active sandbox sessions.</div>';
            });
          });
        }
      }).catch(function(err) {
        diagPanel.innerHTML = '<div style="padding:12px;background:rgba(248,113,113,0.12);border:1px solid var(--red);border-radius:8px;font-size:13px;color:var(--red);">Error: ' + escHtml(String(err)) + '</div>';
      });
    });
  }

  // Wire diagnostics Doctor button
  var rtDoctorBtn = document.getElementById('rt-run-doctor-btn');
  if (rtDoctorBtn) {
    rtDoctorBtn.addEventListener('click', function() {
      var diagPanel = document.getElementById('rt-diagnostics-panel');
      if (!diagPanel) return;
      // Make iframe relative so panels push it down
      var iframe = document.getElementById('runtime-preview-iframe');
      if (iframe) { iframe.style.position = 'relative'; iframe.style.top = '0'; iframe.style.left = '0'; iframe.style.right = '0'; iframe.style.bottom = '0'; iframe.style.width = '100%'; iframe.style.height = '400px'; }
      diagPanel.style.display = 'block';
      diagPanel.innerHTML = '<div style="display:flex;align-items:center;gap:8px;padding:10px 14px;background:var(--bg-input);border-radius:8px;border:1px solid var(--border-color);"><span style="display:inline-block;width:14px;height:14px;border:2px solid var(--accent);border-top-color:transparent;border-radius:50%;animation:spin 0.8s linear infinite;"></span><span style="font-size:12px;color:var(--text-secondary);">Running diagnostics…</span></div>';
      eapi().invoke('diagnostics-run-doctor').then(function(report) {
        if (!report || report.error || !report.checks || report.checks.length === 0) {
          diagPanel.innerHTML = '<div style="padding:12px;color:var(--text-dim);font-size:13px;">No diagnostics results.</div>';
          return;
        }
        var statusIcons = { pass: '<span style="color:var(--green);">✓</span>', warning: '<span style="color:var(--yellow);">⚠</span>', fail: '<span style="color:var(--red);">✗</span>' };
        var html = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;"><span style="font-size:13px;font-weight:600;color:var(--text-primary);">🩺 Diagnostics</span><button id="rt-diag-close" style="background:none;border:none;color:var(--text-dim);cursor:pointer;font-size:14px;">✕</button></div>';
        html += '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:6px;">';
        for (var i = 0; i < report.checks.length; i++) {
          var c = report.checks[i];
          var icon = statusIcons[c.status] || statusIcons.fail;
          html += '<div style="padding:8px 10px;border-left:3px solid var(--' + (c.status === 'pass' ? 'green' : c.status === 'warning' ? 'yellow' : 'red') + ');background:var(--bg-primary);border-radius:4px;">' +
            '<div style="font-size:12px;font-weight:600;">' + icon + ' ' + escHtml(c.name) + '</div>' +
            '<div style="font-size:10px;color:var(--text-secondary);">' + escHtml(c.message) + '</div></div>';
        }
        html += '</div>';
        diagPanel.innerHTML = html;
        var closeBtn = document.getElementById('rt-diag-close');
        if (closeBtn) closeBtn.addEventListener('click', function() { diagPanel.style.display = 'none'; });
      }).catch(function(err) {
        diagPanel.innerHTML = '<div style="padding:12px;background:rgba(248,113,113,0.12);border:1px solid var(--red);border-radius:8px;font-size:13px;color:var(--red);">Error: ' + escHtml(String(err)) + '</div>';
      });
    });
  }

  // Wire Security Scan button
  var rtSecBtn = document.getElementById('rt-run-security-btn');
  if (rtSecBtn) {
    rtSecBtn.addEventListener('click', function() {
      var secPanel = document.getElementById('rt-security-panel');
      if (!secPanel) return;
      var iframe = document.getElementById('runtime-preview-iframe');
      if (iframe) { iframe.style.position = 'relative'; iframe.style.top = '0'; iframe.style.left = '0'; iframe.style.right = '0'; iframe.style.bottom = '0'; iframe.style.width = '100%'; iframe.style.height = '400px'; }
      secPanel.style.display = 'block';
      secPanel.innerHTML = '<div style="display:flex;align-items:center;gap:8px;padding:10px 14px;background:var(--bg-input);border-radius:8px;border:1px solid var(--border-color);"><span style="display:inline-block;width:14px;height:14px;border:2px solid var(--accent);border-top-color:transparent;border-radius:50%;animation:spin 0.8s linear infinite;"></span><span style="font-size:12px;color:var(--text-secondary);">Scanning for security issues…</span></div>';
      eapi().invoke('security-run-scan', { tier: 'extended', projectId: projectId }).then(function(result) {
        if (!result || result.error || !result.summary) {
          secPanel.innerHTML = '<div style="padding:12px;color:var(--text-dim);font-size:13px;">No scan results.</div>';
          return;
        }
        var s = result.summary;
        var html = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;"><span style="font-size:13px;font-weight:600;color:var(--text-primary);">🔒 Security Scan</span><button id="rt-sec-close" style="background:none;border:none;color:var(--text-dim);cursor:pointer;font-size:14px;">✕</button></div>';
        html += '<div style="display:flex;gap:8px;margin-bottom:8px;">' +
          '<div style="padding:6px 10px;background:var(--bg-primary);border:1px solid var(--border-color);border-radius:4px;text-align:center;font-size:11px;"><div style="color:var(--text-dim);">Files</div><div style="font-weight:700;">' + s.totalFiles + '</div></div>' +
          '<div style="padding:6px 10px;background:var(--bg-primary);border:1px solid var(--border-color);border-radius:4px;text-align:center;font-size:11px;"><div style="color:var(--text-dim);">Findings</div><div style="font-weight:700;">' + s.totalFindings + '</div></div>' +
          '<div style="padding:6px 10px;background:var(--bg-primary);border:1px solid var(--border-color);border-radius:4px;text-align:center;font-size:11px;"><div style="color:var(--red);">Critical</div><div style="font-weight:700;">' + (s.findingsBySeverity.critical || 0) + '</div></div>' +
          '<div style="padding:6px 10px;background:var(--bg-primary);border:1px solid var(--border-color);border-radius:4px;text-align:center;font-size:11px;"><div style="color:var(--yellow);">Medium</div><div style="font-weight:700;">' + (s.findingsBySeverity.medium || 0) + '</div></div>' +
          '</div>';
        if (result.findings && result.findings.length > 0) {
          for (var i = 0; i < Math.min(result.findings.length, 10); i++) {
            var f = result.findings[i];
            html += '<div style="padding:6px 10px;border-left:3px solid var(--' + (f.severity === 'critical' || f.severity === 'high' ? 'red' : f.severity === 'medium' ? 'yellow' : 'green') + ');background:var(--bg-primary);border-radius:4px;margin-bottom:3px;">' +
              '<div style="font-size:11px;font-weight:600;">' + escHtml(f.ruleName) + '</div>' +
              '<div style="font-size:10px;color:var(--text-dim);font-family:monospace;">' + escHtml(f.filePath) + ':' + f.line + '</div></div>';
          }
          if (result.findings.length > 10) html += '<div style="font-size:10px;color:var(--text-dim);padding:4px;">...and ' + (result.findings.length - 10) + ' more</div>';
        } else {
          html += '<div style="padding:8px;background:rgba(74,222,128,0.12);border:1px solid var(--green);border-radius:6px;font-size:12px;color:var(--green);">✓ No security findings</div>';
        }
        secPanel.innerHTML = html;
        var closeBtn = document.getElementById('rt-sec-close');
        if (closeBtn) closeBtn.addEventListener('click', function() { secPanel.style.display = 'none'; });
      }).catch(function(err) {
        secPanel.innerHTML = '<div style="padding:12px;background:rgba(248,113,113,0.12);border:1px solid var(--red);border-radius:8px;font-size:13px;color:var(--red);">Error: ' + escHtml(String(err)) + '</div>';
      });
    });
  }

  // Set up event listeners FIRST so we catch live logs
  _setupRuntimeListeners(projectId);

  // Fetch current status and populate service panels
  eapi().invoke('runtime-status', { projectId: projectId }).then(function(session) {
    console.log('[RuntimeView] runtime-status response:', JSON.stringify(session));
    if (session && session.services) {
      var services = session.services;
      var keys = Object.keys(services);
      for (var i = 0; i < keys.length; i++) {
        var svc = services[keys[i]];
        if (svc) {
          _addServicePanel(projectId, svc.serviceId || keys[i], svc.serviceName || keys[i], svc.status || 'starting', svc.hostPort);
        }
      }
      // Auto-preview: prefer frontend service, fallback to first with a port
      var previewSet = false;
      for (var j = 0; j < keys.length; j++) {
        var s = services[keys[j]];
        var sid = s && (s.serviceId || keys[j]);
        if (s && s.hostPort && (sid === 'frontend' || sid === 'client' || sid === 'web' || sid === 'ui')) {
          _setPreview(s.hostPort, sid);
          previewSet = true;
          break;
        }
      }
      if (!previewSet) {
        for (var k = 0; k < keys.length; k++) {
          var sv = services[keys[k]];
          if (sv && sv.hostPort) {
            _setPreview(sv.hostPort, sv.serviceId || keys[k]);
            break;
          }
        }
      }
    }
  }).catch(function(err) {
    console.error('[NeuroNest] Failed to get runtime status:', err);
  });

  // Replay buffered logs from the main process
  eapi().invoke('runtime-get-logs', { projectId: projectId }).then(function(logs) {
    console.log('[RuntimeView] runtime-get-logs response: ' + (logs ? logs.length : 0) + ' lines');
    if (logs && logs.length) {
      for (var i = 0; i < logs.length; i++) {
        appendRuntimeLog(logs[i].serviceId, logs[i].line);
      }
    }
  }).catch(function() {});
}

/**
 * Add a service panel with its own log area to the left panel.
 */
function _addServicePanel(projectId, serviceId, name, status, port) {
  var container = document.getElementById('runtime-services-panel');
  if (!container) return;
  var existing = document.getElementById('runtime-svc-' + serviceId);
  if (existing) {
    _updateServicePanelStatus(serviceId, status, port);
    return;
  }

  var panel = document.createElement('div');
  panel.id = 'runtime-svc-' + serviceId;
  panel.className = 'rv-svc-panel';
  panel.setAttribute('data-service-id', serviceId);

  // Header row: status dot + name + port + controls + preview button
  var hdr = document.createElement('div');
  hdr.className = 'rv-svc-header';
  hdr.innerHTML = '<div style="display:flex;align-items:center;gap:6px;">' +
    '<span class="runtime-status-dot" style="' + _statusDotStyle(status) + '"></span>' +
    '<span style="font-size:12px;font-weight:600;">' + escHtml(name) + '</span>' +
    '<span class="rv-svc-port" style="font-size:10px;color:var(--text-dim);">' + (port ? ':' + port : '') + '</span>' +
    '</div>' +
    '<div style="display:flex;align-items:center;">' +
    '<div class="rv-svc-controls">' +
    '<button class="rv-ctrl" data-action="restart" data-sid="' + escHtml(serviceId) + '" title="Restart">↻</button>' +
    '<button class="rv-ctrl" data-action="stop" data-sid="' + escHtml(serviceId) + '" title="Stop">■</button>' +
    '</div>' +
    '<button class="rv-preview-btn' + (_runtimePreviewServiceId === serviceId ? ' active' : '') + '" data-sid="' + escHtml(serviceId) + '" data-port="' + (port || '') + '" title="Show in preview">👁</button>' +
    '</div>';

  // Wire control buttons
  var ctrls = hdr.querySelectorAll('.rv-ctrl');
  for (var i = 0; i < ctrls.length; i++) {
    (function(btn) {
      btn.addEventListener('click', function(ev) {
        ev.stopPropagation();
        var action = btn.getAttribute('data-action');
        var sid = btn.getAttribute('data-sid');
        if (action === 'restart') {
          eapi().invoke('runtime-restart', { projectId: projectId, serviceId: sid });
        } else if (action === 'stop') {
          eapi().invoke('runtime-stop', { projectId: projectId });
        }
      });
    })(ctrls[i]);
  }

  // Wire preview button
  var prevBtn = hdr.querySelector('.rv-preview-btn');
  if (prevBtn) {
    prevBtn.addEventListener('click', function(ev) {
      ev.stopPropagation();
      var p = prevBtn.getAttribute('data-port');
      var sid = prevBtn.getAttribute('data-sid');
      if (p) _setPreview(parseInt(p, 10), sid);
    });
  }

  panel.appendChild(hdr);

  // Log area for this service
  var logArea = document.createElement('div');
  logArea.id = 'runtime-log-' + serviceId;
  logArea.className = 'rv-svc-log';
  var waitingMsg = document.createElement('div');
  waitingMsg.style.cssText = 'color:#666;font-style:italic;';
  waitingMsg.textContent = 'Waiting for logs...';
  waitingMsg.className = 'rv-log-placeholder';
  logArea.appendChild(waitingMsg);
  panel.appendChild(logArea);

  // Log area is always visible — no toggle
  container.appendChild(panel);
}

/**
 * Update a service panel's status dot and port.
 */
function _updateServicePanelStatus(serviceId, status, port) {
  var panel = document.getElementById('runtime-svc-' + serviceId);
  if (!panel) return;
  var dot = panel.querySelector('.runtime-status-dot');
  if (dot) dot.style.cssText = _statusDotStyle(status);
  var portEl = panel.querySelector('.rv-svc-port');
  if (portEl && port) portEl.textContent = ':' + port;
  // Update preview button port
  var prevBtn = panel.querySelector('.rv-preview-btn');
  if (prevBtn && port) prevBtn.setAttribute('data-port', String(port));
}

/**
 * Set the preview iframe to a specific port/service.
 */
function _setPreview(port, serviceId) {
  _runtimePreviewServiceId = serviceId;
  var previewHeader = document.getElementById('runtime-preview-header');
  if (previewHeader) previewHeader.textContent = 'Live Preview — ' + serviceId + ' :' + port;

  // Update active state on preview buttons
  var btns = document.querySelectorAll('.rv-preview-btn');
  for (var i = 0; i < btns.length; i++) {
    if (btns[i].getAttribute('data-sid') === serviceId) {
      btns[i].classList.add('active');
    } else {
      btns[i].classList.remove('active');
    }
  }

  // Retry loading the URL — the server may not be ready yet
  var url = 'http://localhost:' + port;
  var iframe = document.getElementById('runtime-preview-iframe');
  if (!iframe) return;

  function tryLoad(attempt) {
    if (attempt > 15) {
      console.warn('[RuntimeView] Preview: gave up after 15 attempts for', url);
      // Final fallback: try /index.html directly
      iframe.src = url + '/index.html';
      return;
    }
    console.log('[RuntimeView] Preview: loading attempt', attempt, url);
    iframe.src = url;
    // Retry after a delay if the server isn't ready
    setTimeout(function() {
      try {
        // If iframe loaded something (even an error page), the server is up
        if (iframe.contentWindow && iframe.contentWindow.document && iframe.contentWindow.document.body) {
          return;
        }
      } catch (e) {
        // Cross-origin — means it loaded something, which is good
        return;
      }
      // If we get here, nothing loaded — retry
      tryLoad(attempt + 1);
    }, 2000);
  }

  // Start trying after a short delay to let the server boot
  setTimeout(function() { tryLoad(1); }, 3000);
}

/**
 * Get inline style for a status indicator dot.
 */
function _statusDotStyle(status) {
  var base = 'display:inline-block;width:8px;height:8px;border-radius:50%;flex-shrink:0;';
  if (status === 'starting') return base + 'background:#f1c40f;animation:runtime-pulse 1.2s ease-in-out infinite;';
  if (status === 'running') return base + 'background:#2ecc71;';
  if (status === 'failed') return base + 'background:#e74c3c;';
  return base + 'background:#95a5a6;'; // stopped / default
}

/**
 * Update a service's status and port in the Runtime View.
 */
function updateServiceStatus(serviceId, status, port) {
  _updateServicePanelStatus(serviceId, status, port);
  // If panel doesn't exist yet, create it
  if (!document.getElementById('runtime-svc-' + serviceId)) {
    _addServicePanel(_runtimeViewProjectId, serviceId, serviceId, status, port);
  }
  // Auto-set preview: prefer frontend, otherwise first running service
  if (status === 'running' && port) {
    var isFrontend = (serviceId === 'frontend' || serviceId === 'client' || serviceId === 'web' || serviceId === 'ui');
    if (isFrontend || !_runtimePreviewServiceId) {
      _setPreview(port, serviceId);
    }
  }
}

/**
 * Append a log line for a service — writes directly to that service's log panel.
 * Creates the service panel if it doesn't exist yet.
 */
function appendRuntimeLog(serviceId, line) {
  if (!_runtimeLogs[serviceId]) _runtimeLogs[serviceId] = [];
  _runtimeLogs[serviceId].push(line);

  // Create the service panel if it doesn't exist yet
  if (!document.getElementById('runtime-svc-' + serviceId)) {
    console.log('[RuntimeView] Creating panel for:', serviceId);
    _addServicePanel(_runtimeViewProjectId, serviceId, serviceId, 'starting', null);
  }

  var logEl = document.getElementById('runtime-log-' + serviceId);
  if (logEl) {
    // Remove placeholder on first real log
    var placeholder = logEl.querySelector('.rv-log-placeholder');
    if (placeholder) placeholder.remove();

    var lineEl = document.createElement('div');
    // Strip ANSI escape codes for clean display
    var cleanLine = line.replace(/\x1b\[[0-9;]*m/g, '');
    lineEl.textContent = cleanLine;
    // Color-code different log types
    if (cleanLine.startsWith('[env]') || cleanLine.startsWith('[scaffold]')) {
      lineEl.style.color = '#60a5fa';
    } else if (cleanLine.startsWith('[install]')) {
      lineEl.style.color = '#fbbf24';
    } else if (cleanLine.startsWith('[run]')) {
      lineEl.style.color = '#34d399';
    } else if (cleanLine.startsWith('Error') || cleanLine.startsWith('[error]')) {
      lineEl.style.color = '#f87171';
    }
    logEl.appendChild(lineEl);
    logEl.scrollTop = logEl.scrollHeight;
  } else {
    console.warn('[RuntimeView] Log element not found: runtime-log-' + serviceId);
  }
}

/**
 * Set up runtime event listeners for log and status updates.
 */
function _setupRuntimeListeners(projectId) {
  var api = eapi();

  var logHandler = function(data) {
    if (!data || data.projectId !== projectId) return;
    console.log('[RuntimeView] log event:', data.serviceId, (data.line || '').substring(0, 60));
    appendRuntimeLog(data.serviceId, data.line);
  };

  var statusHandler = function(data) {
    if (!data || data.projectId !== projectId) return;
    console.log('[RuntimeView] status event:', data.serviceId, data.status, data.port);
    updateServiceStatus(data.serviceId, data.status, data.port);
    if (!document.getElementById('runtime-svc-' + data.serviceId)) {
      _addServicePanel(projectId, data.serviceId, data.serviceId, data.status, data.port);
    }
  };

  api.on('runtime-log', logHandler);
  api.on('runtime-status-update', statusHandler);

  _runtimeLogListeners = function() {
    api.removeListener('runtime-log', logHandler);
    api.removeListener('runtime-status-update', statusHandler);
  };
}

/**
 * Clean up runtime event listeners.
 */
function _cleanupRuntimeListeners() {
  if (_runtimeLogListeners) {
    _runtimeLogListeners();
    _runtimeLogListeners = null;
  }
}

// Export runtime view functions for tests
if (typeof window !== 'undefined') {
  window.showRuntimeView = showRuntimeView;
  window.updateServiceStatus = updateServiceStatus;
  window.appendRuntimeLog = appendRuntimeLog;
}
